using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.Text;
using System.Threading;
using SailwindRadio;

// Ogg Vorbis decoder checks. Source audio is synthetic, generated by Signal. Vorbis is lossy, so the
// oracle is ffmpeg's libvorbis decoder (the reference decoder) and its native decoder, both to f32le.
// Committed fixtures carry sample points from that oracle in Fixtures/expected.txt, so the decoder is
// also checked against the reference when ffmpeg is absent.
// Usage: VorbisChecks [--regen] [--no-ffmpeg] [--ffmpeg path]
// ffmpeg is --ffmpeg, then RADIO_CHECKS_FFMPEG, then ffmpeg on PATH. Without it the oracle checks skip.
static class VorbisChecks
{
    static int checks;
    static readonly List<string> skipped = new List<string>();
    static readonly List<string> report = new List<string>();
    static string testDir, fixtureDir, scratchDir, ffmpeg;
    // Bump when Signal or scratch specs change so cached scratch files are regenerated.
    const string ScratchVersion = "v1";
    // Maximum absolute difference from the reference decoder. Vorbis decoding is deterministic up to float
    // rounding. The measured worst case is near 2e-7, so 1e-5 leaves wide margin for rounding while any
    // real fault (a window, a coefficient, a one-sample shift) shows as errors of 1e-3 or more.
    const double Tolerance = 1e-5;
    const double RmsTolerance = 1e-6;

    static void Check(bool result, string message) { if (!result) throw new Exception("Check failed: " + message); checks++; }
    static void Skip(string what) { skipped.Add(what); Console.WriteLine("SKIP " + what); }
    static string F(double v, string format) { return v.ToString(format, CultureInfo.InvariantCulture); }

    static int Main(string[] args)
    {
        try
        {
            testDir = FindTestDir();
            fixtureDir = Path.Combine(testDir, "Fixtures");
            scratchDir = Path.GetFullPath(Path.Combine(testDir, "..", "..", ".local", "vorbis"));
            Directory.CreateDirectory(scratchDir);
            bool regen = false, noFfmpeg = false;
            string ffmpegArgument = null;
            for (int i = 0; i < args.Length; i++)
            {
                if (args[i] == "--regen") regen = true;
                else if (args[i] == "--no-ffmpeg") noFfmpeg = true;
                else if (args[i] == "--ffmpeg" && i + 1 < args.Length) ffmpegArgument = args[++i];
            }
            ffmpeg = noFfmpeg ? null : FindFfmpeg(ffmpegArgument);
            if (args.Length == 1 && args[0] == "--write-floor0")
            {
                // The playback checks open this synthetic floor 0 stream through the production opener.
                File.WriteAllBytes(FixturePath(Floor0Fixture), Floor0Stream());
                return 0;
            }
            if (regen)
            {
                if (ffmpeg == null) throw new Exception("--regen needs ffmpeg");
                RegenerateFixtures();
                return 0;
            }
            var total = Stopwatch.StartNew();
            UnitChecks();
            OggLayerChecks();
            FixtureChecks();
            SyntheticChecks();
            ContainerChecks();
            RejectionChecks();
            ErrorChecks();
            SeekChecks();
            AllocationChecks();
            if (ffmpeg != null)
            {
                OracleChecks();
                MatrixChecks();
                LongFileChecks();
                HourFileChecks();
            }
            else
            {
                Skip("full-length comparison of committed fixtures with ffmpeg (ffmpeg not found)");
                Skip("ffmpeg encoder matrix (ffmpeg not found)");
                Skip("5-minute speed, full comparison and seek checks (ffmpeg not found)");
                Skip("60-minute seek cost check (ffmpeg not found)");
            }
            foreach (string line in report) Console.WriteLine(line);
            Console.WriteLine(checks + " Vorbis checks passed in " + F(total.Elapsed.TotalSeconds, "0.0") + " s on " + RuntimeName() +
                (skipped.Count == 0 ? ", none skipped" : ", " + skipped.Count + " skipped"));
            return 0;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine(ex);
            return 1;
        }
    }

    // An explicit path that does not exist skips the ffmpeg checks rather than falling back to PATH.
    static string FindFfmpeg(string argument)
    {
        string chosen = !string.IsNullOrEmpty(argument) ? argument : Environment.GetEnvironmentVariable("RADIO_CHECKS_FFMPEG");
        if (!string.IsNullOrEmpty(chosen)) return File.Exists(chosen) ? chosen : null;
        foreach (string dir in (Environment.GetEnvironmentVariable("PATH") ?? "").Split(Path.PathSeparator))
            foreach (string name in new[] { "ffmpeg.exe", "ffmpeg" })
            {
                try { string candidate = Path.Combine(dir.Trim().Trim('"'), name); if (File.Exists(candidate)) return candidate; }
                catch (ArgumentException) { }
            }
        return null;
    }

    static string RuntimeName() { return Type.GetType("Mono.Runtime") != null ? "Mono" : ".NET " + Environment.Version; }

    static string FindTestDir()
    {
        string dir = AppDomain.CurrentDomain.BaseDirectory;
        while (dir != null)
        {
            if (File.Exists(Path.Combine(dir, "VorbisChecks.csproj"))) return dir;
            string nested = Path.Combine(dir, "tests", "Vorbis");
            if (File.Exists(Path.Combine(nested, "VorbisChecks.csproj"))) return nested;
            dir = Path.GetDirectoryName(dir.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));
        }
        throw new Exception("Cannot locate tests/Vorbis");
    }

    // ---- Unit checks ----

    static void UnitChecks()
    {
        Check(TestOgg.Crc(Encoding.ASCII.GetBytes("123456789")) == 0x89A1897Fu, "Independent CRC-32 (poly 0x04C11DB7, init 0) check value");
        var page = new byte[60];
        new Rng(3).Fill(page);
        Array.Copy(Encoding.ASCII.GetBytes("OggS"), page, 4);
        page[26] = 1;
        page[27] = 32;
        var zeroed = (byte[])page.Clone();
        zeroed[22] = zeroed[23] = zeroed[24] = zeroed[25] = 0;
        Check(OggReader.Crc(page, 0, 60) == TestOgg.Crc(zeroed), "Page CRC treats the checksum field as zero");

        // Inverse MDCT against the O(N^2) definition.
        foreach (int n in new[] { 64, 128, 256, 512, 2048, 8192 })
        {
            var rng = new Rng((ulong)n);
            var x = new float[n / 2];
            for (int i = 0; i < x.Length; i++) x[i] = (float)(rng.NextDouble() * 2 - 1);
            var y = new float[n];
            new VorbisMdct(n).Inverse(x, y);
            double max = 0, peak = 0;
            int stride = n > 2048 ? 7 : 1;
            for (int j = 0; j < n; j += stride)
            {
                double s = 0;
                for (int k = 0; k < n / 2; k++) s += x[k] * Math.Cos(2 * Math.PI / n * (j + 0.5 + n / 4.0) * (k + 0.5));
                max = Math.Max(max, Math.Abs(s - y[j]));
                peak = Math.Max(peak, Math.Abs(s));
            }
            Check(max < 2e-6 * Math.Max(1, peak) * Math.Log(n), "Inverse MDCT matches the definition for N=" + n + " (error " + max + ")");
        }

        // floor1_inverse_dB_table values quoted from the specification and libvorbis.
        var known = new Dictionary<int, double> { { 0, 1.0649863e-07 }, { 1, 1.1341951e-07 }, { 7, 1.6548181e-07 }, { 180, 0.0088964928 },
            { 212, 0.066714279 }, { 252, 0.82788260 }, { 253, 0.88168307 }, { 254, 0.9389798 }, { 255, 1.0 } };
        foreach (var kv in known)
            Check(Math.Abs(VorbisFloor1.InverseDb[kv.Key] / kv.Value - 1) < 1e-6, "Inverse dB table entry " + kv.Key);

        foreach (int n in new[] { 32, 128, 1024, 4096 })
        {
            float[] w = VorbisCodec.Slope(n);
            double worst = 0;
            for (int i = 0; i < n; i++) worst = Math.Max(worst, Math.Abs(w[i] * (double)w[i] + w[n - 1 - i] * (double)w[n - 1 - i] - 1));
            Check(worst < 1e-6 && w[0] > 0 && w[n - 1] <= 1 && w[0] < w[n - 1], "Window slope of " + n + " is power complementary");
        }

        // Codeword assignment example from the specification, section 3.2.1.
        byte[] lengths = { 2, 4, 4, 4, 4, 2, 3, 3 };
        var codes = new uint[8];
        Check(VorbisCodebook.AssignCodewords(lengths, codes), "Specification codeword example assigns");
        string[] expect = { "00", "0100", "0101", "0110", "0111", "10", "110", "111" };
        for (int i = 0; i < 8; i++)
        {
            string bits = "";
            for (int b = 0; b < lengths[i]; b++) bits += ((codes[i] >> (31 - b)) & 1) != 0 ? "1" : "0";
            Check(bits == expect[i], "Codeword " + i + " is " + expect[i]);
        }
        Check(!VorbisCodebook.AssignCodewords(new byte[] { 1, 1, 1 }, new uint[3]), "Overspecified lengths are rejected");

        Check(VorbisCodebook.Unpack(TestVorbis.Pack(-1.0)) == -1f && VorbisCodebook.Unpack(TestVorbis.Pack(0.125)) == 0.125f &&
            VorbisCodebook.Unpack(TestVorbis.Pack(-2.5)) == -2.5f && VorbisCodebook.Unpack(0) == 0f, "float32_unpack");
        Check(VorbisCodebook.Lookup1Values(81, 4) == 3 && VorbisCodebook.Lookup1Values(80, 4) == 2 && VorbisCodebook.Lookup1Values(1089, 2) == 33 &&
            VorbisCodebook.Lookup1Values(256, 1) == 256 && VorbisCodebook.Lookup1Values(255, 8) == 1 && VorbisCodebook.Lookup1Values(5, 60000) == 1, "lookup1_values");
        Check(VorbisCodec.ILog(0) == 0 && VorbisCodec.ILog(1) == 1 && VorbisCodec.ILog(7) == 3 && VorbisCodec.ILog(8) == 4 && VorbisCodec.ILog(-3) == 0, "ilog");

        // The Vorbis I layouts give exactly the coefficients this decoder had before the shared downmix.
        const double h = 0.70710678118654752;
        double[][] expectLeft =
        {
            new[] { 1, h, 0 }, new[] { 1, 0, h, 0 }, new[] { 1, h, 0, h, 0 }, new[] { 1, h, 0, h, 0, 0 },
            new[] { 1, h, 0, h, 0, 0.5, 0 }, new[] { 1, h, 0, h, 0, h, 0, 0 },
        };
        double[][] expectRight =
        {
            new[] { 0, h, 1 }, new[] { 0, 1, 0, h }, new[] { 0, h, 1, 0, h }, new[] { 0, h, 1, 0, h, 0 },
            new[] { 0, h, 1, 0, h, 0.5, 0 }, new[] { 0, h, 1, 0, h, 0, h, 0 },
        };
        for (int channels = 3; channels <= 10; channels++)
        {
            float[] l, r;
            ChannelDownmix.Build(ChannelDownmix.Vorbis(channels), out l, out r);
            double[] el = new double[channels], er = new double[channels];
            if (channels <= 8) { el = expectLeft[channels - 3]; er = expectRight[channels - 3]; }
            else for (int c = 0; c < channels; c++) { el[c] = (c & 1) == 0 ? 1 : 0; er[c] = 1 - el[c]; }
            double el1 = 0, er1 = 0;
            foreach (double w in el) el1 += w;
            foreach (double w in er) er1 += w;
            // Symmetric layouts keep the earlier per-row coefficients bit for bit. Only an odd channel count
            // above eight is asymmetric, and both its rows share the louder row's divisor to keep the balance.
            bool symmetric = el1 == er1;
            Check(symmetric == (channels <= 8 || channels % 2 == 0), "Only odd Vorbis channel counts above eight are asymmetric: " + channels);
            double divisor = Math.Max(el1, er1);
            bool same = true;
            for (int c = 0; c < channels; c++)
                same &= symmetric ? l[c] == (float)(el[c] / el1) && r[c] == (float)(er[c] / er1) :
                    l[c] == (float)(el[c] / divisor) && r[c] == (float)(er[c] / divisor);
            Check(same, "Shared downmix " + (symmetric ? "keeps" : "balances") + " the Vorbis coefficients for " + channels + " channels");
            double sl = 0, sr = 0;
            for (int c = 0; c < channels; c++) { sl += Math.Abs(l[c]); sr += Math.Abs(r[c]); }
            Check(l.Length == channels && Math.Abs(Math.Max(sl, sr) - 1) < 1e-6 && Math.Abs(sl / sr - el1 / er1) < 1e-6 && l[0] > 0 && r[0] == 0,
                "Downmix rows for " + channels + " channels peak at unit weight and keep their left and right balance");
            if (channels <= 8)
            {
                int right = channels == 4 ? 1 : 2;
                Check(r[right] > 0 && l[right] == 0, "Front right stays right for " + channels + " channels");
                if (channels >= 6) Check(l[channels - 1] == 0 && r[channels - 1] == 0, "LFE dropped for " + channels + " channels");
                if (channels != 4) Check(l[1] == r[1] && l[1] > 0, "Centre split evenly for " + channels + " channels");
            }
        }
        Console.WriteLine("unit checks done");
    }

    // ---- Ogg container layer on synthetic pages ----

    static void OggLayerChecks()
    {
        var rng = new Rng(77);
        int[] sizes = { 0, 1, 254, 255, 256, 510, 1000, 70000, 3, 0, 765, 12 };
        var packets = new List<byte[]>();
        var granules = new List<long>();
        long g = 0;
        foreach (int size in sizes)
        {
            var p = new byte[size];
            rng.Fill(p);
            packets.Add(p);
            g += 100;
            granules.Add(g);
        }
        const uint serial = 0x1234ABCD;
        var pages = TestOgg.BuildPages(serial, packets, granules, 3000, true, null, 0);
        byte[] stream = TestOgg.Join(pages);
        var reader = new OggReader(new MemoryStream(stream), CancellationToken.None);
        reader.Select(serial, long.MaxValue);
        OggPacket got;
        int index = 0;
        long lastGranule = -1;
        while (reader.NextPacket(int.MaxValue, out got))
        {
            Check(index < packets.Count && got.Length == packets[index].Length && got.TotalLength == got.Length && Same(got.Data, packets[index], got.Length) && !got.Hole,
                "Packet " + index + " of " + packets[index].Length + " bytes reassembled");
            if (got.Granule >= 0)
            {
                Check(got.LastOnPage && got.Granule == granules[index], "Page granule belongs to the last packet completed on it");
                lastGranule = got.Granule;
            }
            index++;
        }
        Check(index == packets.Count && lastGranule == granules[granules.Count - 1] && reader.CrcFailures == 0, "All packets read and EOS ends the stream");

        // Store limits keep counting the full length.
        reader.SeekTo(0);
        for (int i = 0; i < 8; i++) reader.NextPacket(100, out got);
        Check(got.Length == 100 && got.TotalLength == 70000, "Store limit truncates the copy but reports the full packet length");

        // Junk between pages and a foreign stream are skipped without a hole.
        var otherPages = TestOgg.BuildPages(99, new List<byte[]> { new byte[500], new byte[40000] }, new List<long> { 1, 2 }, 2000, true, null, 0);
        var mixed = new List<byte[]>();
        for (int i = 0; i < pages.Count; i++)
        {
            mixed.Add(pages[i]);
            if (i < otherPages.Count) mixed.Add(otherPages[i]);
            if (i % 3 == 1) mixed.Add(Encoding.ASCII.GetBytes("junk OggS junk " + i));
        }
        var readMixed = ReadAllPackets(TestOgg.Join(mixed), serial);
        Check(readMixed.Count == packets.Count && !readMixed.Exists(p => p.Hole), "Foreign pages and junk are skipped without holes");
        for (int i = 0; i < packets.Count; i++) Check(Same(readMixed[i].Data, packets[i], packets[i].Length), "Mixed stream packet " + i);

        // A lost page reports a hole and drops the packets that touched it.
        int lost = FindPageWithContinuation(pages);
        var gap = new List<byte[]>(pages);
        gap.RemoveAt(lost);
        var readGap = ReadAllPackets(TestOgg.Join(gap), serial);
        Check(readGap.Exists(p => p.Hole) && readGap.Count < packets.Count, "Lost page reports a hole");
        foreach (var p in readGap) Check(packets.Exists(q => q.Length == p.Data.Length && Same(p.Data, q, q.Length)), "Packets around a hole are intact or dropped, never spliced");

        // A CRC failure is a lost page too, and counts as a failure.
        var damaged = new List<byte[]>(pages);
        damaged[lost] = (byte[])pages[lost].Clone();
        damaged[lost][damaged[lost].Length - 5] ^= 0x40;
        var crcReader = new OggReader(new MemoryStream(TestOgg.Join(damaged)), CancellationToken.None);
        crcReader.Select(serial, long.MaxValue);
        bool hole = false;
        while (crcReader.NextPacket(int.MaxValue, out got)) hole |= got.Hole;
        Check(hole && crcReader.CrcFailures == 1, "CRC mismatch drops the page and reports a hole");

        // Seeking to a page start drops the continued fragment without a hole.
        long offset = 0;
        for (int i = 0; i < lost; i++) offset += pages[i].Length;
        reader.SeekTo(offset);
        Check(reader.NextPacket(int.MaxValue, out got) && !got.Hole && packets.Exists(q => q.Length == got.Length && Same(got.Data, q, q.Length)), "Continued fragment after a seek is dropped");

        // Granule bisection, last page search and chain link detection.
        var many = new List<byte[]>();
        var manyGranules = new List<long>();
        for (int i = 0; i < 3000; i++) { var p = new byte[200 + (i * 37) % 900]; rng.Fill(p); many.Add(p); manyGranules.Add(1000L * (i + 1)); }
        var manyPages = TestOgg.BuildPages(7, many, manyGranules, 4000, true, null, 0);
        byte[] manyStream = TestOgg.Join(manyPages);
        var pageList = TestOgg.ParsePages(manyStream);
        var search = new OggReader(new MemoryStream(manyStream), CancellationToken.None);
        foreach (long target in new long[] { 1, 1000, 1001, 250500, 1500000, 2999999, 3000000, 3000001, 99999999 })
        {
            TestOgg.PageRec best = null;
            foreach (var pr in pageList) if (pr.Granule >= 0 && pr.Granule < target) best = pr;
            OggPage found;
            bool ok = search.FindGranuleBefore(7, target, 0, manyStream.Length, out found);
            Check(ok == (best != null) && (!ok || found.Offset == best.Offset), "Granule bisection for " + target);
        }
        OggPage lastPage;
        Check(search.FindLastPage(manyStream.Length, 0, 7, true, out lastPage) && lastPage.Granule == 3000000, "Last page search");
        var chain = TestOgg.Join(new List<byte[]> { manyStream, stream });
        Check(search.FindLinkEnd(0, new uint[] { 7 }) == manyStream.Length, "Unchained stream has no link end before the file end");
        var chainReader = new OggReader(new MemoryStream(chain), CancellationToken.None);
        Check(chainReader.FindLinkEnd(0, new uint[] { 7 }) == manyStream.Length, "Chain link boundary found by bisection");
        Console.WriteLine("Ogg layer checks done");
    }

    static int FindPageWithContinuation(List<byte[]> pages)
    {
        for (int i = 2; i < pages.Count - 1; i++) if ((pages[i + 1][5] & 1) != 0) return i;
        throw new Exception("test stream has no spanning packet");
    }

    sealed class Pkt { public byte[] Data; public bool Hole; public long Granule; }

    static List<Pkt> ReadAllPackets(byte[] stream, uint serial)
    {
        var reader = new OggReader(new MemoryStream(stream), CancellationToken.None);
        reader.Select(serial, long.MaxValue);
        var list = new List<Pkt>();
        OggPacket p;
        while (reader.NextPacket(int.MaxValue, out p))
        {
            var copy = new byte[p.Length];
            Buffer.BlockCopy(p.Data, 0, copy, 0, p.Length);
            list.Add(new Pkt { Data = copy, Hole = p.Hole, Granule = p.Granule });
        }
        return list;
    }

    static bool Same(byte[] a, byte[] b, int n)
    {
        if (a.Length < n || b.Length < n) return false;
        for (int i = 0; i < n; i++) if (a[i] != b[i]) return false;
        return true;
    }

    // ---- Committed fixtures ----

    sealed class Fixture
    {
        public string Name, Args; public int Channels, Rate; public long Frames; public Signal Signal;
        // Frames from the recorded reference instead of the source length, for encoders that pad.
        public bool Padded;
        // The only audio page is also the last page, where ffmpeg's Ogg demuxer disagrees with the specification.
        public bool SinglePage;
        public double MinSnr = double.NaN;
        public Action<Decoded> Expect;
        public Fixture(string name, Signal signal, int channels, int rate, long frames, string args)
        { Name = name; Signal = signal; Channels = channels; Rate = rate; Frames = frames; Args = args; }
    }

    static Fixture[] Fixtures()
    {
        var music = new Signal("music", 1);
        var list = new List<Fixture>
        {
            new Fixture("stereo44-q-1", music, 2, 44100, 66150, "-c:a libvorbis -q:a -1") { MinSnr = 20 },
            new Fixture("stereo44-q2", music, 2, 44100, 66150, "-c:a libvorbis -q:a 2") { MinSnr = 20 },
            new Fixture("stereo44-q6", music, 2, 44100, 44100, "-c:a libvorbis -q:a 6") { MinSnr = 25 },
            new Fixture("stereo44-q10", music, 2, 44100, 66150, "-c:a libvorbis -q:a 10") { MinSnr = 30 },
            new Fixture("mono8-q2", music, 1, 8000, 16000, "-c:a libvorbis -q:a 2") { MinSnr = 20 },
            new Fixture("mono22-q4", music, 1, 22050, 44100, "-c:a libvorbis -q:a 4") { MinSnr = 20 },
            new Fixture("stereo48-transients-q4", new Signal("transients", 2), 2, 48000, 72000, "-c:a libvorbis -q:a 4")
                { MinSnr = 3, Expect = d => Check(d.Stats.ShortBlocks > 0 && d.Stats.TransitionBlocks > 0, "transients force short blocks and long-short transitions") },
            new Fixture("stereo96-q4", music, 2, 96000, 192000, "-c:a libvorbis -q:a 4") { MinSnr = 20 },
            new Fixture("stereo192-q4", music, 2, 192000, 288000, "-c:a libvorbis -q:a 4") { MinSnr = 20 },
            new Fixture("surround51-q3", music, 6, 48000, 72000, "-c:a libvorbis -q:a 3") { Expect = d => Check(d.Src == 6 && d.Out == 2, "5.1 folds to stereo") },
            new Fixture("surround71-q3", music, 8, 48000, 72000, "-c:a libvorbis -q:a 3") { Expect = d => Check(d.Src == 8 && d.Out == 2, "7.1 folds to stereo") },
            new Fixture("tiny-mono44", music, 1, 44100, 300, "-c:a libvorbis -q:a 4") { SinglePage = true, MinSnr = 15 },
            new Fixture("single-page-stereo192", music, 2, 192000, 96000, "-c:a libvorbis -q:a 4") { SinglePage = true, MinSnr = 20 },
            new Fixture("comments-stereo22-q2", music, 2, 22050, 22050, "-c:a libvorbis -q:a 2") { MinSnr = 15 },
            new Fixture("native-stereo44", music, 2, 44100, 88200, "-c:a vorbis -strict experimental") { Padded = true },
            new Fixture("native-stereo22", new Signal("mix", 3), 2, 22050, 44100, "-c:a vorbis -strict experimental") { Padded = true },
            new Fixture("silence-stereo44-q4", new Signal("silence", 4), 2, 44100, 110250, "-c:a libvorbis -q:a 4")
                { Expect = d => Check(d.Stats.UnusedFloors > 0 && MaxAbs(d.Samples) == 0, "silence decodes to zeros through unused floors") },
            new Fixture("noise-mono44-q6", new Signal("noise", 5), 1, 44100, 44100, "-c:a libvorbis -q:a 6") { MinSnr = 8 },
            new Fixture("mix-stereo32-q0", new Signal("mix", 6), 2, 32000, 64000, "-c:a libvorbis -q:a 0") { MinSnr = 7 },
        };
        return list.ToArray();
    }

    const string ChainedFixture = "chained-mono22-stereo44";
    // Written by --write-floor0 from the synthetic encoder. Floor 0 is rejected, so it has no expected samples.
    const string Floor0Fixture = "floor0-synthetic";
    static byte[] Floor0Stream() { long frames; return TestVorbis.Build(2, 10, 5, false, 0, out frames, "floor0"); }
    const string MuxedFixture = "theora-vorbis22";
    static readonly string[] RejectFixtures = { "opus", "oggflac", "speex", "theora" };
    static readonly string[] RejectMessages = { "Ogg Opus audio is not supported", "Ogg FLAC audio is not supported", "Ogg Speex audio is not supported",
        "Ogg Theora video without Vorbis audio is not supported" };

    static string FixturePath(string name) { return Path.Combine(fixtureDir, name + ".ogg"); }

    static void RegenerateFixtures()
    {
        Directory.CreateDirectory(fixtureDir);
        string src = Path.Combine(scratchDir, "fixture-sources");
        Directory.CreateDirectory(src);
        foreach (var fx in Fixtures())
        {
            string wav = Path.Combine(src, fx.Name + ".wav");
            WriteWav(wav, fx.Signal, fx.Channels, fx.Rate, fx.Frames);
            string extra = "";
            if (fx.Name.StartsWith("comments"))
            {
                string meta = Path.Combine(src, "comments.txt");
                var sb = new StringBuilder(";FFMETADATA1\ntitle=Synthetic Tone \u00e9\nartist=Nobody\ncomment=");
                var rng = new Rng(11);
                for (int i = 0; i < 90000; i++) sb.Append((char)('a' + (int)(rng.Next() % 26)));
                sb.Append('\n');
                File.WriteAllText(meta, sb.ToString(), new UTF8Encoding(false));
                RunFfmpeg("-i \"" + wav + "\" -i \"" + meta + "\" -map 0:a -map_metadata 1 " + fx.Args + " \"" + FixturePath(fx.Name) + "\"");
                continue;
            }
            RunFfmpeg("-i \"" + wav + "\" " + fx.Args + extra + " \"" + FixturePath(fx.Name) + "\"");
        }
        // Chained: two independently encoded streams, byte concatenated.
        string a = Path.Combine(src, "chain-a.wav"), b = Path.Combine(src, "chain-b.wav");
        WriteWav(a, new Signal("music", 7), 1, 22050, 11025);
        WriteWav(b, new Signal("music", 8), 2, 44100, 22050);
        RunFfmpeg("-i \"" + a + "\" -c:a libvorbis -q:a 2 \"" + Path.Combine(src, "chain-a.ogg") + "\"");
        RunFfmpeg("-i \"" + b + "\" -c:a libvorbis -q:a 2 \"" + Path.Combine(src, "chain-b.ogg") + "\"");
        File.WriteAllBytes(FixturePath(ChainedFixture), TestOgg.Join(new List<byte[]> { File.ReadAllBytes(Path.Combine(src, "chain-a.ogg")), File.ReadAllBytes(Path.Combine(src, "chain-b.ogg")) }));
        // Multiplexed Theora and Vorbis.
        string v = Path.Combine(src, "muxed.wav");
        WriteWav(v, new Signal("music", 9), 1, 22050, 22050);
        RunFfmpeg("-f lavfi -i testsrc=size=32x32:rate=4:duration=1 -i \"" + v + "\" -c:v libtheora -q:v 0 -c:a libvorbis -q:a 0 \"" + FixturePath(MuxedFixture) + "\"");
        // Other Ogg codecs, for rejection.
        string r = Path.Combine(src, "reject.wav");
        WriteWav(r, new Signal("music", 10), 1, 16000, 3200);
        RunFfmpeg("-i \"" + r + "\" -c:a libopus -b:a 16k \"" + FixturePath("opus") + "\"");
        RunFfmpeg("-i \"" + r + "\" -c:a flac -f ogg \"" + FixturePath("oggflac") + "\"");
        RunFfmpeg("-i \"" + r + "\" -c:a libspeex \"" + FixturePath("speex") + "\"");
        RunFfmpeg("-f lavfi -i testsrc=size=32x32:rate=4:duration=0.5 -c:v libtheora -q:v 0 \"" + FixturePath("theora") + "\"");

        // Reference sample points from the libvorbis decoder.
        var lines = new List<string>();
        long totalBytes = 0;
        foreach (string file in Directory.GetFiles(fixtureDir, "*.ogg")) totalBytes += new FileInfo(file).Length;
        foreach (var fx in Fixtures()) lines.Add(ExpectedLine(fx.Name, File.ReadAllBytes(FixturePath(fx.Name)), FixturePath(fx.Name)));
        lines.Add(ExpectedLine(ChainedFixture, File.ReadAllBytes(Path.Combine(src, "chain-a.ogg")), Path.Combine(src, "chain-a.ogg")));
        lines.Add(ExpectedLine(MuxedFixture, File.ReadAllBytes(FixturePath(MuxedFixture)), FixturePath(MuxedFixture)));
        foreach (var syn in SyntheticStreams())
        {
            string path = Path.Combine(src, syn.Name + ".ogg");
            File.WriteAllBytes(path, syn.Data);
            lines.Add(ExpectedLine(syn.Name, syn.Data, path, !syn.NativeOracle));
        }
        File.WriteAllText(Path.Combine(fixtureDir, "expected.txt"), string.Join("\n", lines) + "\n", new UTF8Encoding(false));
        foreach (string file in Directory.GetFiles(fixtureDir, "*.ogg")) Console.WriteLine(Path.GetFileName(file) + " " + new FileInfo(file).Length + " bytes");
        Console.WriteLine("fixtures total " + totalBytes + " bytes");
    }

    // name frames=N ffmpeg=N channels=C rate=R points=index:value,...
    static string ExpectedLine(string name, byte[] data, string path, bool libvorbis = true)
    {
        var d = DecodeAll(data);
        float[] reference = Reference(path, libvorbis, d.Src);
        long refFrames = reference.Length / d.Out;
        var sb = new StringBuilder();
        sb.Append(name).Append(" frames=").Append(d.Frames).Append(" ffmpeg=").Append(refFrames).Append(" channels=").Append(d.Out).Append(" rate=").Append(d.Rate).Append(" points=");
        long n = Math.Min(d.Frames, refFrames) * d.Out;
        var points = new SortedSet<long>();
        for (int i = 0; i < 64; i++) points.Add(n * i / 64);
        for (int i = 1; i <= 4; i++) { points.Add(n - i); points.Add(i - 1); }
        bool first = true;
        foreach (long i in points)
        {
            if (i < 0 || i >= n) continue;
            if (!first) sb.Append(',');
            first = false;
            sb.Append(i).Append(':').Append(reference[i].ToString("R", CultureInfo.InvariantCulture));
        }
        return sb.ToString();
    }

    sealed class ExpectedData { public long Frames, FfmpegFrames; public int Channels, Rate; public List<KeyValuePair<long, float>> Points = new List<KeyValuePair<long, float>>(); }

    static Dictionary<string, ExpectedData> LoadExpected()
    {
        var map = new Dictionary<string, ExpectedData>();
        foreach (string line in File.ReadAllLines(Path.Combine(fixtureDir, "expected.txt")))
        {
            if (line.Trim().Length == 0) continue;
            string[] parts = line.Split(' ');
            var e = new ExpectedData();
            foreach (string part in parts)
            {
                int eq = part.IndexOf('=');
                if (eq < 0) continue;
                string key = part.Substring(0, eq), value = part.Substring(eq + 1);
                if (key == "frames") e.Frames = long.Parse(value, CultureInfo.InvariantCulture);
                else if (key == "ffmpeg") e.FfmpegFrames = long.Parse(value, CultureInfo.InvariantCulture);
                else if (key == "channels") e.Channels = int.Parse(value, CultureInfo.InvariantCulture);
                else if (key == "rate") e.Rate = int.Parse(value, CultureInfo.InvariantCulture);
                else if (key == "points")
                    foreach (string point in value.Split(','))
                    {
                        int colon = point.IndexOf(':');
                        e.Points.Add(new KeyValuePair<long, float>(long.Parse(point.Substring(0, colon), CultureInfo.InvariantCulture),
                            float.Parse(point.Substring(colon + 1), CultureInfo.InvariantCulture)));
                    }
            }
            map[parts[0]] = e;
        }
        return map;
    }

    static void CheckPoints(string name, Decoded d, ExpectedData e)
    {
        Check(d.Out == e.Channels && d.Rate == e.Rate && d.Frames == e.Frames, "Recorded stream properties " + name);
        double max = 0;
        foreach (var p in e.Points) max = Math.Max(max, Math.Abs(p.Value - d.Samples[p.Key]));
        Check(max <= Tolerance, name + " matches recorded libvorbis sample points (max error " + max + ")");
    }

    static void FixtureChecks()
    {
        var expected = LoadExpected();
        long totalBytes = 0;
        foreach (string file in Directory.GetFiles(fixtureDir, "*.ogg"))
        {
            long size = new FileInfo(file).Length;
            totalBytes += size;
            Check(size < 200 * 1024, "Fixture stays small " + Path.GetFileName(file));
        }
        Check(totalBytes < 1536 * 1024, "Committed fixtures total under 1.5 MB");
        var snrs = new List<string>();
        foreach (var fx in Fixtures())
        {
            string path = FixturePath(fx.Name);
            Check(File.Exists(path), "Committed fixture exists " + fx.Name);
            var d = DecodeAll(File.ReadAllBytes(path));
            Check(d.Src == fx.Channels && d.Rate == fx.Rate && d.Out == Math.Min(2, fx.Channels), "Stream properties " + fx.Name);
            ExpectedData e;
            Check(expected.TryGetValue(fx.Name, out e), "Recorded reference for " + fx.Name);
            if (!fx.Padded) Check(d.Frames == fx.Frames, "Exact source length " + fx.Name + " (" + d.Frames + ")");
            else Check(d.Frames == e.FfmpegFrames && d.Frames >= fx.Frames && d.Frames < fx.Frames + 2 * d.BlockSize1, "Padded length equals ffmpeg " + fx.Name);
            Check(fx.SinglePage == (CountGranulePages(File.ReadAllBytes(path)) == 1), "Fixture page layout is as intended " + fx.Name);
            if (fx.SinglePage) Check(e.FfmpegFrames != d.Frames && d.StartGranule == 0, "Single audio page ends at its granule, where ffmpeg's demuxer differs " + fx.Name);
            else Check(d.Frames == e.FfmpegFrames, "Frame count equals ffmpeg " + fx.Name);
            CheckPoints(fx.Name, d, e);
            if (!double.IsNaN(fx.MinSnr))
            {
                double best;
                int shift;
                double snr = Snr(d, fx.Signal, out best, out shift);
                snrs.Add(fx.Name + " " + F(snr, "0.0") + " dB");
                Check(snr >= fx.MinSnr && shift == 0, "Decoded audio follows the source without delay " + fx.Name + " (SNR " + F(snr, "0.0") + " dB, best shift " + shift + ")");
            }
            if (fx.Expect != null) fx.Expect(d);
        }
        Console.WriteLine("committed fixtures verified (" + totalBytes / 1024 + " KB)");
        report.Add("SNR against the synthetic source: " + string.Join(", ", snrs));
    }

    static int CountGranulePages(byte[] data)
    {
        int count = 0;
        foreach (var p in TestOgg.ParsePages(data)) if (p.Granule > 0) count++;
        return count;
    }

    static double MaxAbs(float[] s) { double m = 0; foreach (float v in s) m = Math.Max(m, Math.Abs(v)); return m; }

    // SNR of the decode against the 16-bit source, at the best of a few small shifts.
    static double Snr(Decoded d, Signal s, out double best, out int bestShift)
    {
        best = double.MinValue;
        bestShift = 0;
        double atZero = 0;
        for (int shift = -3; shift <= 3; shift++)
        {
            double signal = 0, noise = 0;
            for (long i = 64; i < d.Frames - 64; i++)
                for (int c = 0; c < d.Out; c++)
                {
                    double x = s.Sample16(c, i + shift, d.Rate) / 32768.0, y = d.Samples[i * d.Out + c];
                    signal += x * x;
                    noise += (x - y) * (x - y);
                }
            double snr = 10 * Math.Log10(signal / Math.Max(noise, 1e-30));
            if (shift == 0) atZero = snr;
            if (snr > best) { best = snr; bestShift = shift; }
        }
        return atZero;
    }

    // ---- Synthetic streams with features libvorbis never emits ----

    sealed class Synthetic { public string Name; public byte[] Data; public long Frames; public bool NativeOracle; }

    static List<Synthetic> SyntheticStreams()
    {
        var list = new List<Synthetic>();
        long frames;
        byte[] data = TestVorbis.Build(3, 120, 101, false, 0, out frames);
        list.Add(new Synthetic { Name = "synthetic-3ch", Data = data, Frames = frames });
        data = TestVorbis.Build(2, 90, 202, true, 100, out frames);
        list.Add(new Synthetic { Name = "synthetic-2ch-eop-endtrim", Data = data, Frames = frames });
        data = TestVorbis.Build(1, 60, 303, false, 0, out frames);
        list.Add(new Synthetic { Name = "synthetic-1ch", Data = data, Frames = frames });
        data = TestVorbis.Build(1, 80, 404, false, 0, out frames, null, true);
        list.Add(new Synthetic { Name = "synthetic-1ch-native", Data = data, Frames = frames, NativeOracle = true });
        return list;
    }

    static void SyntheticChecks()
    {
        var expected = LoadExpected();
        var totals = new VorbisStatistics();
        foreach (var syn in SyntheticStreams())
        {
            var d = DecodeAll(syn.Data);
            Check(d.Frames == syn.Frames, "Synthetic stream length " + syn.Name);
            ExpectedData e;
            Check(expected.TryGetValue(syn.Name, out e), "Recorded reference for " + syn.Name);
            CheckPoints(syn.Name, d, e);
            Check(d.Frames == e.FfmpegFrames, "Synthetic frame count equals ffmpeg " + syn.Name);
            for (int i = 0; i < 3; i++) { totals.LookupTypes[i] += d.Stats.LookupTypes[i]; totals.ResidueTypesUsed[i] += d.Stats.ResidueTypesUsed[i]; }
            totals.MaxSubmaps = Math.Max(totals.MaxSubmaps, d.Stats.MaxSubmaps);
            totals.MaxCouplingSteps = Math.Max(totals.MaxCouplingSteps, d.Stats.MaxCouplingSteps);
            totals.UnusedFloors += d.Stats.UnusedFloors;
            totals.TransitionBlocks += d.Stats.TransitionBlocks;
            totals.ShortBlocks += d.Stats.ShortBlocks;
            SeekSeries("synthetic " + syn.Name, syn.Data, 25);
        }
        Check(totals.LookupTypes[0] > 0 && totals.LookupTypes[1] > 0 && totals.LookupTypes[2] > 0, "Codebook lookup types 0, 1 and 2 exercised");
        Check(totals.ResidueTypesUsed[0] > 0 && totals.ResidueTypesUsed[1] > 0 && totals.ResidueTypesUsed[2] > 0, "Residue types 0, 1 and 2 exercised");
        Check(totals.MaxSubmaps == 2 && totals.MaxCouplingSteps == 2 && totals.UnusedFloors > 0 && totals.TransitionBlocks > 0 && totals.ShortBlocks > 0,
            "Submaps, chained coupling, unused floors and block transitions exercised");
        Console.WriteLine("synthetic stream checks done");
    }

    // ---- Container variations built from fixtures ----

    static void ContainerChecks()
    {
        byte[] baseFile = File.ReadAllBytes(FixturePath("stereo44-q2"));
        var original = DecodeAll(baseFile);
        var parsed = TestOgg.ParsePackets(baseFile);
        long[] ends = PacketEnds(parsed, baseFile);
        uint serial = parsed.Serial;
        var headerFlush = new HashSet<int> { 0, 2 };

        // Repaging never changes the decoded audio.
        var layouts = new[] { new[] { 0, 1 }, new[] { 100, 0 }, new[] { 65025, 0 }, new[] { 4000, 0 } };
        string[] layoutNames = { "one packet per page", "100-byte pages", "maximal pages", "4000-byte pages" };
        for (int i = 0; i < layouts.Length; i++)
        {
            HashSet<int> flush = new HashSet<int>(headerFlush);
            if (layouts[i][1] == 1) for (int k = 0; k < parsed.Packets.Count; k++) flush.Add(k);
            int maxBody = layouts[i][0] == 0 ? 65025 : layouts[i][0];
            byte[] repaged = TestOgg.Join(TestOgg.BuildPages(serial, parsed.Packets, new List<long>(ends), maxBody, true, flush, 0));
            var d = DecodeAll(repaged);
            CheckIdentical(d, original, 0, original.Frames, "repaged " + layoutNames[i]);
            if (i == 1) SeekSeries("100-byte pages", repaged, 30);
        }

        // No EOS flag, empty and non-audio packets, and an ID3v2 prefix change nothing.
        {
            var packets = new List<byte[]>(parsed.Packets);
            var granules = new List<long>(ends);
            for (int k = packets.Count - 2; k > 4; k -= 7)
            {
                packets.Insert(k, new byte[0]);
                granules.Insert(k, -2);
                packets.Insert(k, new byte[] { 0xFF, 1, 2 });
                granules.Insert(k, -2);
            }
            // Inserted packets produce nothing, so they take the previous packet's end.
            for (int k = 0; k < granules.Count; k++) if (granules[k] == -2) granules[k] = granules[k - 1];
            byte[] odd = TestOgg.Join(TestOgg.BuildPages(serial, packets, granules, 3000, false, headerFlush, 0));
            var d = DecodeAll(odd);
            CheckIdentical(d, original, 0, original.Frames, "empty and non-audio packets without EOS");
            Check(d.Stats.SkippedPackets > 0, "Non-audio packets are skipped");
            var id3 = new byte[10 + 300];
            id3[0] = (byte)'I'; id3[1] = (byte)'D'; id3[2] = (byte)'3'; id3[3] = 4; id3[8] = 300 >> 7; id3[9] = 300 & 0x7F;
            CheckIdentical(DecodeAll(TestOgg.Join(new List<byte[]> { id3, baseFile })), original, 0, original.Frames, "ID3v2 prefix");
            byte[] junk = TestOgg.Join(TestOgg.ParsePages(baseFile).ConvertAll(p => TestOgg.Join(new List<byte[]> { Slice(baseFile, (int)p.Offset, p.Size), Encoding.ASCII.GetBytes("garbage OggS") })));
            CheckIdentical(DecodeAll(junk), original, 0, original.Frames, "garbage between pages");
        }

        // Granule offsets: a positive start keeps every sample, a negative start trims the beginning,
        // and a short final granule trims the end.
        {
            long firstAudioEnd = FirstPageAudioSamples(parsed, ends);
            foreach (long shift in new long[] { 100000, -7, -(firstAudioEnd - 1) })
            {
                var shifted = new List<long>(ends);
                for (int k = 3; k < shifted.Count; k++) shifted[k] += shift;
                byte[] data = TestOgg.Join(TestOgg.BuildPages(serial, parsed.Packets, shifted, 4000, true, headerFlush, 0));
                var d = DecodeAll(data);
                long trim = shift < 0 ? -shift : 0;
                Check(d.Frames == original.Frames - trim && d.StartGranule == shift, "Granule shift " + shift + " frames and start");
                CheckIdentical(d, original, trim, d.Frames, "granule shift " + shift);
                if (shift == 100000) SeekSeries("positive start granule", data, 20);
                if (shift == -7) SeekSeries("beginning trim", data, 20);
            }
            var cut = new List<long>(ends);
            cut[cut.Count - 1] -= 333;
            byte[] endTrim = TestOgg.Join(TestOgg.BuildPages(serial, parsed.Packets, cut, 4000, true, headerFlush, 0));
            var e = DecodeAll(endTrim);
            Check(e.Frames == original.Frames - 333, "End trim shortens Frames");
            CheckIdentical(e, original, 0, e.Frames, "end trim");
        }

        // Multiplexed streams: the first Vorbis stream plays and the others are ignored.
        {
            byte[] other = File.ReadAllBytes(FixturePath("mono22-q4"));
            var otherParsed = TestOgg.ParsePackets(other);
            var a = TestOgg.BuildPages(serial, parsed.Packets, new List<long>(ends), 4000, true, headerFlush, 0);
            var b = TestOgg.BuildPages(otherParsed.Serial == serial ? serial + 1 : otherParsed.Serial, otherParsed.Packets, new List<long>(PacketEnds(otherParsed, other)), 1500, true, headerFlush, 0);
            CheckIdentical(DecodeAll(TestOgg.Interleave(a, b, 3, 3)), original, 0, original.Frames, "two multiplexed Vorbis streams");
            var fake = TestOgg.BuildPages(5, new List<byte[]> { Encoding.ASCII.GetBytes("OpusHead\u0001\u0002\u0000\u0000\u0080\u00bb\u0000\u0000\u0000\u0000\u0000"), new byte[3000], new byte[3000] },
                new List<long> { 0, 960, 1920 }, 1000, true, new HashSet<int> { 0 }, 0);
            var dm = DecodeAll(TestOgg.Interleave(fake, a, 1, 3));
            CheckIdentical(dm, original, 0, original.Frames, "Opus then Vorbis group");
            Check(dm.Codecs.Length == 2 && dm.Codecs[0] == "Opus" && dm.Codecs[1] == "Vorbis", "Group codecs identified");
            var muxed = DecodeAll(File.ReadAllBytes(FixturePath(MuxedFixture)));
            Check(muxed.Codecs.Length == 2 && muxed.Codecs[0] == "Theora" && muxed.Codecs[1] == "Vorbis" && muxed.Frames == 22050, "ffmpeg Theora and Vorbis file plays its Vorbis stream");
            CheckPoints(MuxedFixture, muxed, LoadExpected()[MuxedFixture]);
            SeekSeries("Theora multiplexed", File.ReadAllBytes(FixturePath(MuxedFixture)), 20);
        }

        // Chained streams: only the first link plays.
        {
            byte[] chained = File.ReadAllBytes(FixturePath(ChainedFixture));
            var pages = TestOgg.ParsePages(chained);
            long second = -1;
            foreach (var p in pages) if (p.Serial != pages[0].Serial && (p.Flags & 2) != 0) { second = p.Offset; break; }
            var d = DecodeAll(chained);
            var first = DecodeAll(Slice(chained, 0, (int)second));
            Check(d.LinkEnd == second && d.Src == 1 && d.Frames == 11025, "Chained file ends at the second link");
            CheckIdentical(d, first, 0, first.Frames, "chained first link");
            CheckPoints(ChainedFixture, d, LoadExpected()[ChainedFixture]);
            SeekSeries("chained", chained, 20);
            // Without the first link's EOS flag the serial change still ends it.
            var firstParsed = TestOgg.ParsePackets(Slice(chained, 0, (int)second));
            byte[] noEos = TestOgg.Join(TestOgg.BuildPages(firstParsed.Serial, firstParsed.Packets, new List<long>(PacketEnds(firstParsed, Slice(chained, 0, (int)second))), 4000, false, headerFlush, 0));
            byte[] chained2 = TestOgg.Join(new List<byte[]> { noEos, Slice(chained, (int)second, chained.Length - (int)second), baseFile });
            var d2 = DecodeAll(chained2);
            Check(d2.LinkEnd == noEos.Length, "Chain without EOS ends at the next link");
            CheckIdentical(d2, first, 0, first.Frames, "chained without EOS");
        }
        Console.WriteLine("container checks done");
    }

    // Packet end positions: header packets 0, audio packets from block sizes, the last one from its page granule.
    static long[] PacketEnds(TestOgg.Parsed parsed, byte[] file)
    {
        using (var dec = new VorbisDecoder(new MemoryStream(file), CancellationToken.None))
        {
            var ends = new long[parsed.Packets.Count];
            long end = dec.StartGranule;
            int previous = -1;
            for (int k = 3; k < ends.Length; k++)
            {
                int flag = dec.Codec.PeekBlockFlag(parsed.Packets[k], parsed.Packets[k].Length);
                if (flag >= 0)
                {
                    int size = dec.Codec.BlockSize(flag);
                    if (previous >= 0) end += previous / 4 + size / 4;
                    previous = size;
                }
                ends[k] = end;
            }
            ends[ends.Length - 1] = parsed.Granules[ends.Length - 1];
            return ends;
        }
    }

    static long FirstPageAudioSamples(TestOgg.Parsed parsed, long[] ends)
    {
        for (int k = 3; k < ends.Length; k++) if (parsed.Granules[k] >= 0) return ends[k] - ends[3];
        return 0;
    }

    static void CheckIdentical(Decoded d, Decoded original, long offset, long frames, string name)
    {
        Check(d.Frames == frames && d.Out == original.Out, "Length of " + name);
        int ch = d.Out;
        for (long i = 0; i < frames * ch; i++)
            if (d.Samples[i] != original.Samples[i + offset * ch]) Check(false, name + " differs at sample " + i);
        checks++;
    }

    // ---- Rejection ----

    static void RejectionChecks()
    {
        for (int i = 0; i < RejectFixtures.Length; i++)
        {
            string message = DecodeError(File.ReadAllBytes(FixturePath(RejectFixtures[i])));
            Check(message == RejectMessages[i], RejectFixtures[i] + " rejected as: " + message);
        }
        Check(DecodeError(new byte[0]) == "File is not an Ogg stream", "Empty input rejected");
        Check(DecodeError(Encoding.ASCII.GetBytes("RIFF\0\0\0\0WAVEfmt ")) == "File is not an Ogg stream", "WAV input rejected");
        Check(DecodeError(File.ReadAllBytes(Path.Combine(testDir, "..", "Flac", "Fixtures", "mono16-l5.flac"))) == "File is not an Ogg stream", "Native FLAC rejected");
        byte[] good = File.ReadAllBytes(FixturePath("mono8-q2"));
        byte[] bad = (byte[])good.Clone();
        bad[40] ^= 1;
        Check(DecodeError(bad) == "Ogg stream start is damaged", "Damaged first page rejected");
        var pages = TestOgg.ParsePages(good);
        bad = (byte[])good.Clone();
        bad[pages[1].Offset + pages[1].Size / 2] ^= 1;
        Check(DecodeError(bad) == "Vorbis headers are incomplete", "Damaged setup page rejected");
        Check(DecodeError(Slice(good, 0, (int)pages[2].Offset)) == "Ogg Vorbis stream has no audio", "Headers without audio rejected");

        // Hand-built setup headers for error paths no encoder produces.
        string[] faults = { "floor0", "floortype", "residuetype", "mappingtype", "coupling", "timedomain", "codebooksync", "lookuptype", "framing", "modemapping", "overspecified", "duplicatex", "residuebook", "hugebook" };
        string[] messages = { "Vorbis floor 0 is not supported", "Vorbis floor type is invalid", "Vorbis residue type is invalid", "Vorbis mapping type is invalid",
            "Vorbis channel coupling is invalid", "Vorbis time domain transform is invalid", "Vorbis codebook sync pattern is invalid", "Vorbis codebook lookup type is invalid",
            "Vorbis setup header framing bit is missing", "Vorbis mode mapping is invalid", "Vorbis codebook is overspecified", "Vorbis floor 1 has duplicate points",
            "Vorbis residue codebook has no vector lookup", "Vorbis codebook is too large" };
        for (int i = 0; i < faults.Length; i++)
        {
            long frames;
            byte[] data = TestVorbis.Build(2, 10, 5, false, 0, out frames, faults[i]);
            string message = DecodeError(data);
            Check(message == messages[i], "Setup fault " + faults[i] + " rejected as: " + message);
        }
        byte[] floor0 = File.ReadAllBytes(FixturePath(Floor0Fixture));
        Check(Convert.ToBase64String(floor0) == Convert.ToBase64String(Floor0Stream()) && DecodeError(floor0) == "Vorbis floor 0 is not supported",
            "Committed floor 0 fixture matches its generator and is rejected");
        try { new VorbisDecoder(new NonSeekable(good), CancellationToken.None); Check(false, "Non-seekable stream rejected"); }
        catch (IOException ex) { Check(ex.Message == "Ogg input must be a seekable stream", "Non-seekable stream rejected with IOException"); }
        Console.WriteLine("rejection checks done");
    }

    static string DecodeError(byte[] data)
    {
        try
        {
            using (var d = new VorbisDecoder(new MemoryStream(data), CancellationToken.None))
            {
                var buffer = new float[8192];
                while (d.Read(buffer, 0, buffer.Length) > 0) { }
            }
            return null;
        }
        catch (InvalidDataException ex) { Check(ex.Message.IndexOf(';') < 0, "No semicolons in error messages"); return ex.Message; }
        catch (IOException ex) { Check(ex.Message.IndexOf(';') < 0, "No semicolons in error messages"); return ex.Message; }
    }

    sealed class NonSeekable : MemoryStream
    {
        public NonSeekable(byte[] data) : base(data) { }
        public override bool CanSeek { get { return false; } }
    }

    // ---- Damage ----

    static void ErrorChecks()
    {
        // The fixture repaged into 1500-byte pages, which decodes identically, so damage hits many pages.
        byte[] fixture = File.ReadAllBytes(FixturePath("stereo44-q2"));
        var parsed = TestOgg.ParsePackets(fixture);
        byte[] good = TestOgg.Join(TestOgg.BuildPages(parsed.Serial, parsed.Packets, new List<long>(PacketEnds(parsed, fixture)), 1500, true, new HashSet<int> { 0, 2 }, 0));
        var original = DecodeAll(good);
        var pages = TestOgg.ParsePages(good);
        Check(pages.Count > 12, "Damage test stream has many pages");
        int bs1 = original.BlockSize1;

        // A damaged audio page: exact outside the lost span, silence inside, same length.
        foreach (int which in new[] { 4, pages.Count / 2, pages.Count - 2 })
        {
            var victim = pages[which];
            byte[] bad = (byte[])good.Clone();
            bad[victim.Offset + victim.Size - 10] ^= 0x22;
            var d = DecodeAll(bad);
            Check(d.Frames == original.Frames && d.Stats.Holes >= 1, "Damaged page " + which + " keeps the length and reports a hole (" + d.Frames + " of " + original.Frames + ", holes " + d.Stats.Holes + ")");
            // Recovery anchors on the next page that completes a packet it started, at most two pages on.
            long before = PreviousGranule(pages, which) - original.StartGranule, after = pages[Math.Min(which + 2, pages.Count - 1)].Granule - original.StartGranule;
            for (long i = 0; i < d.Frames * 2; i++)
            {
                long frame = i / 2;
                if (frame >= before && frame < after) continue;
                if (which == pages.Count - 2 && frame >= before) continue;
                if (d.Samples[i] != original.Samples[i]) Check(false, "Damaged page " + which + " changes frame " + frame + " outside the lost span " + before + "-" + after);
            }
            checks++;
            // Seeking into and past the damage works.
            using (var dec = new VorbisDecoder(new MemoryStream(bad), CancellationToken.None))
            {
                var buffer = new float[2000];
                dec.Seek(Math.Max(0, after + bs1));
                int got = dec.Read(buffer, 0, buffer.Length);
                long from = after + bs1;
                if (from < original.Frames)
                    for (int i = 0; i < got; i++) Check(buffer[i] == original.Samples[from * 2 + i], "Seek past damage reads original audio");
                dec.Seek(Math.Max(0, (before + after) / 2));
                dec.Read(buffer, 0, buffer.Length);
            }
        }

        // A lost page followed by hundreds of packets on pages without granules keeps the recovery queue
        // bounded, and the audio from the next granule on is exact.
        {
            long synthetic;
            byte[] source = TestVorbis.Build(1, 1400, 707, false, 0, out synthetic);
            var sp = TestOgg.ParsePackets(source);
            var ends = new List<long>(PacketEnds(sp, source));
            for (int k = 60; k < 960; k++) ends[k] = -1;
            byte[] withheld = TestOgg.Join(TestOgg.BuildPages(sp.Serial, sp.Packets, ends, 1500, true, new HashSet<int> { 0, 2 }, 0));
            var reference = DecodeAll(withheld);
            var wp = TestOgg.ParsePages(withheld);
            int lost = wp.FindIndex(2, pg => pg.Granule < 0);
            int anchor = wp.FindIndex(lost, pg => pg.Granule >= 0);
            byte[] damaged = (byte[])withheld.Clone();
            damaged[wp[lost].Offset + wp[lost].Size - 3] ^= 0x40;
            long anchorFrame = wp[anchor].Granule - reference.StartGranule;
            using (var dec = new VorbisDecoder(new MemoryStream(damaged), CancellationToken.None))
            {
                var all = new float[dec.Frames * dec.Channels];
                int read = 0, got;
                while ((got = dec.Read(all, read, Math.Min(4096, all.Length - read))) > 0) read += got;
                int queued = ((Array)typeof(VorbisDecoder).GetField("queue", System.Reflection.BindingFlags.Instance |
                    System.Reflection.BindingFlags.NonPublic).GetValue(dec)).Length;
                Check(read == all.Length && dec.Frames == reference.Frames && dec.Statistics.Holes >= 1 && queued <= 512 && anchor - lost > 20,
                    "Withheld granules after a lost page keep the recovery queue bounded: queue " + queued + " over " + (anchor - lost) + " pages");
                for (long i = anchorFrame * dec.Channels; i < all.Length; i++)
                    if (all[i] != reference.Samples[i]) Check(false, "Audio after the withheld granules differs at sample " + i);
                checks++;
            }
        }

        // Truncation: either a clear error or a clean decode that ends at the last complete page.
        var rng = new Rng(4);
        var cuts = new List<int> { 0, 1, 27, 57, 58, 200, (int)pages[1].Offset + 10, (int)pages[2].Offset, (int)pages[2].Offset + 30, good.Length - 1, good.Length - 30 };
        for (int i = 0; i < 30; i++) cuts.Add((int)(rng.Next() % (ulong)good.Length));
        int errors = 0, clean = 0;
        foreach (int cut in cuts)
        {
            var sw = Stopwatch.StartNew();
            byte[] part = Slice(good, 0, cut);
            string message = null;
            Decoded d = null;
            try { d = DecodeAll(part); }
            catch (InvalidDataException ex) { message = ex.Message; }
            Check(sw.ElapsedMilliseconds < 5000, "Truncated at " + cut + " finishes quickly");
            long lastGranule = -1, firstGranulePage = -1;
            TestOgg.PageRec lastComplete = null;
            foreach (var p in pages)
            {
                if (p.Offset + p.Size > cut) break;
                if (p.Granule > 0) { lastGranule = p.Granule; lastComplete = p; if (firstGranulePage < 0) firstGranulePage = p.Offset; }
            }
            if (lastGranule <= 0)
            {
                Check(message != null, "Truncated at " + cut + " before audio is rejected");
                errors++;
                continue;
            }
            Check(message == null, "Truncated at " + cut + " decodes: " + message);
            clean++;
            if (lastComplete.Offset == firstGranulePage) continue;
            Check(d.Frames == lastGranule - original.StartGranule, "Truncated at " + cut + " ends at the last complete page");
            CheckIdentical(d, original, 0, d.Frames, "truncated at " + cut);
        }

        // Random damage. Only InvalidDataException or IOException may escape, quickly. The stream engine bounds the output.
        long synthFrames;
        byte[][] sources = { File.ReadAllBytes(FixturePath("mono22-q4")), good, TestVorbis.Build(3, 40, 505, false, 0, out synthFrames) };
        int failures = 0, successes = 0;
        var fuzzTime = Stopwatch.StartNew();
        // VORBIS_CHECKS_FUZZ raises the iteration count for longer campaigns.
        int iterations = 300;
        string fuzzSetting = Environment.GetEnvironmentVariable("VORBIS_CHECKS_FUZZ");
        if (!string.IsNullOrEmpty(fuzzSetting)) iterations = int.Parse(fuzzSetting, CultureInfo.InvariantCulture);
        for (int iteration = 0; iteration < iterations; iteration++)
        {
            byte[] fuzz = (byte[])sources[iteration % 3].Clone();
            int flips = 1 + (int)(rng.Next() % 8);
            int range = iteration % 4 == 3 ? 4200 : fuzz.Length;
            for (int f = 0; f < flips; f++) fuzz[rng.Next() % (ulong)range] ^= (byte)(1 << (int)(rng.Next() % 8));
            if (iteration % 5 == 0) fuzz = Slice(fuzz, 0, (int)(rng.Next() % (ulong)fuzz.Length));
            if (iteration % 7 == 0)
            {
                // Recompute page CRCs so damage reaches the codec instead of the container.
                TestOgg.FixCrcs(fuzz);
            }
            try
            {
                using (var dec = new VorbisDecoder(new MemoryStream(fuzz), CancellationToken.None))
                {
                    var buffer = new float[4096];
                    if (iteration % 2 == 1) dec.Seek((long)(rng.Next() % (ulong)Math.Max(1, dec.Frames)));
                    long total = 0;
                    int got;
                    while ((got = dec.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        total += got;
                        if (total > 100000000) throw new Exception("fuzz decode does not end");
                    }
                    Check(dec.Position == dec.Frames, "Fuzz decode reaches Frames");
                }
                successes++;
            }
            catch (InvalidDataException ex) { failures++; Check(ex.Message.IndexOf(';') < 0, "Error messages carry no semicolons"); }
            catch (IOException) { failures++; }
        }
        Check(fuzzTime.ElapsedMilliseconds < 60000L * Math.Max(1, iterations / 300), "Fuzz finishes promptly");
        report.Add("damage: truncation " + errors + " rejected and " + clean + " clean, fuzz " + failures + " rejected and " + successes + " decoded, " + fuzzTime.ElapsedMilliseconds + " ms");

        // Cancellation stops construction and decoding.
        using (var cts = new CancellationTokenSource())
        {
            var dec = new VorbisDecoder(new MemoryStream(good), cts.Token);
            cts.Cancel();
            bool cancelled = false;
            try { dec.Read(new float[8192], 0, 8192); } catch (OperationCanceledException) { cancelled = true; }
            Check(cancelled, "Cancellation token stops decoding");
            cancelled = false;
            try { dec.Seek(original.Frames / 2); dec.Read(new float[100], 0, 100); } catch (OperationCanceledException) { cancelled = true; }
            Check(cancelled, "Cancellation token stops seeking");
            bool threw = false;
            try { new VorbisDecoder(new MemoryStream(good), cts.Token); } catch (OperationCanceledException) { threw = true; }
            Check(threw, "Cancellation token stops construction");
        }
        using (var dec = new VorbisDecoder(new MemoryStream(good), CancellationToken.None))
        {
            dec.Dispose();
            bool threw = false;
            try { dec.Read(new float[10], 0, 10); } catch (ObjectDisposedException) { threw = true; }
            Check(threw, "Read after Dispose throws ObjectDisposedException");
        }
        Console.WriteLine("error checks done");
    }

    static long PreviousGranule(List<TestOgg.PageRec> pages, int index)
    {
        for (int i = index - 1; i >= 0; i--) if (pages[i].Granule >= 0) return pages[i].Granule;
        return 0;
    }

    // ---- Seeking on committed fixtures ----

    static void SeekChecks()
    {
        foreach (var name in new[] { "stereo44-q2", "stereo48-transients-q4", "mono8-q2", "surround51-q3", "native-stereo44", "tiny-mono44", "single-page-stereo192", "stereo192-q4" })
            SeekSeries(name, File.ReadAllBytes(FixturePath(name)), 60);
        byte[] data = File.ReadAllBytes(FixturePath("stereo44-q2"));
        var full = DecodeAll(data);
        long frames = full.Frames;
        using (var d = new VorbisDecoder(new MemoryStream(data), CancellationToken.None))
        {
            var buffer = new float[1000];
            d.Seek(frames + 500);
            Check(d.Position == frames && d.Read(buffer, 0, buffer.Length) == 0, "Seek past end clamps and reads nothing");
            d.Seek(frames);
            Check(d.Read(buffer, 0, buffer.Length) == 0, "Seek to end reads nothing");
            d.Seek(frames - 1);
            Check(d.Read(buffer, 0, buffer.Length) == 2 && d.Position == frames && buffer[0] == full.Samples[(frames - 1) * 2], "Seek to last frame reads one frame");
            d.Seek(0);
            Check(d.Read(buffer, 0, 3) == 2 && buffer[0] == full.Samples[0] && buffer[1] == full.Samples[1], "Seek to zero and odd count reads whole frames only");
            bool threw = false;
            try { d.Seek(-1); } catch (ArgumentOutOfRangeException) { threw = true; }
            Check(threw, "Negative seek rejected");
            Check(d.Read(buffer, 0, 1) == 0 && d.Position == 1, "Count below one frame reads nothing without advancing");
            d.Seek(1000);
            buffer[4] = 7;
            Check(d.Read(buffer, 5, 4) == 4 && buffer[4] == 7 && buffer[5] == full.Samples[2000] && buffer[8] == full.Samples[2003], "Read honours the output offset");
            threw = false;
            try { d.Read(buffer, 999, 2); } catch (ArgumentOutOfRangeException) { threw = true; }
            Check(threw, "Read range beyond the buffer rejected");
        }
        Console.WriteLine("small seek checks done");
    }

    // Random seeks, near the start and end, repeated and short forward jumps, all against a full decode.
    static void SeekSeries(string name, byte[] data, int count)
    {
        var full = DecodeAll(data);
        long frames = full.Frames;
        int ch = full.Out;
        using (var d = new VorbisDecoder(new MemoryStream(data), CancellationToken.None))
        {
            var rng = new Rng(99);
            var buffer = new float[3000 * ch];
            long last = -1;
            for (int i = 0; i < count; i++)
            {
                long target;
                switch (i)
                {
                    case 0: target = 0; break;
                    case 1: target = frames - 1; break;
                    case 2: target = Math.Min(frames - 1, 1); break;
                    case 3: target = Math.Max(0, frames - 5000); break;
                    case 4: target = last; break;
                    default: target = i % 7 == 0 ? Math.Min(frames - 1, last + 10) : i % 11 == 0 ? Math.Max(0, last - 700) : (long)(rng.NextDouble() * frames); break;
                }
                d.Seek(target);
                Check(d.Position == target, "Position after seek " + name);
                int want = i % 3 == 0 ? buffer.Length : 7 * ch;
                int got = d.Read(buffer, 0, want);
                long expectFrames = Math.Min(want / ch, frames - target);
                Check(got == expectFrames * ch, "Read length after seek " + name + " to " + target);
                for (long f = 0; f < expectFrames * ch; f++)
                    if (buffer[f] != full.Samples[target * ch + f]) Check(false, "Seek " + name + " to " + target + " differs at frame " + (target + f / ch));
                last = target;
            }
            checks++;
        }
    }

    // ---- Steady state allocations ----

    static void AllocationChecks()
    {
        var method = typeof(GC).GetMethod("GetAllocatedBytesForCurrentThread", Type.EmptyTypes);
        if (method == null)
        {
            Skip("allocation measurement (runtime has no per-thread allocation counter)");
            return;
        }
        byte[] data = File.ReadAllBytes(FixturePath("stereo44-q2"));
        using (var d = new VorbisDecoder(new MemoryStream(data), CancellationToken.None))
        {
            var buffer = new float[4096];
            d.Read(buffer, 0, buffer.Length);
            d.Seek(40000);
            d.Read(buffer, 0, buffer.Length);
            d.Seek(0);
            d.Read(buffer, 0, buffer.Length);
            long before = (long)method.Invoke(null, null);
            for (int pass = 0; pass < 3; pass++)
            {
                d.Seek(0);
                while (d.Read(buffer, 0, buffer.Length) > 0) { }
                d.Seek(30000 + pass * 1000);
                d.Read(buffer, 0, buffer.Length);
            }
            long allocated = (long)method.Invoke(null, null) - before;
            report.Add("steady state allocations over three full decodes and seeks: " + allocated + " bytes");
            Check(allocated < 16 * 1024, "No per-packet allocations in steady state (" + allocated + " bytes)");
        }
    }

    // ---- ffmpeg oracle on committed fixtures, full length ----

    sealed class ErrorStats { public double Max, Rms; public long Frames; }

    static ErrorStats Compare(Decoded d, float[] reference, string name)
    {
        int ch = d.Out;
        long n = Math.Min(d.Frames, reference.Length / ch) * ch;
        double max = 0, sum = 0;
        for (long i = 0; i < n; i++)
        {
            double e = Math.Abs(d.Samples[i] - reference[i]);
            sum += e * e;
            if (e > max) max = e;
        }
        var stats = new ErrorStats { Max = max, Rms = Math.Sqrt(sum / Math.Max(1, n)), Frames = n / ch };
        Check(stats.Max <= Tolerance && stats.Rms <= RmsTolerance, name + " within tolerance of ffmpeg (max " + stats.Max + ", rms " + stats.Rms + ")");
        return stats;
    }

    static double nativeEncoderDivergence;

    // Error statistics without a tolerance check, for reporting a known divergence.
    static ErrorStats Difference(Decoded d, float[] reference)
    {
        int ch = d.Out;
        long n = Math.Min(d.Frames, reference.Length / ch) * ch;
        double max = 0, sum = 0;
        for (long i = 0; i < n; i++) { double e = Math.Abs(d.Samples[i] - reference[i]); sum += e * e; if (e > max) max = e; }
        return new ErrorStats { Max = max, Rms = Math.Sqrt(sum / Math.Max(1, n)), Frames = n / ch };
    }

    static void OracleChecks()
    {
        var lines = new List<string>();
        foreach (var fx in Fixtures())
        {
            string path = FixturePath(fx.Name);
            var d = DecodeAll(File.ReadAllBytes(path));
            float[] lib = Reference(path, true, d.Src), native = Reference(path, false, d.Src);
            if (!fx.SinglePage) Check(d.Frames == lib.Length / d.Out && d.Frames == native.Length / d.Out, "Frame count equals both ffmpeg decoders " + fx.Name);
            var a = Compare(d, lib, fx.Name + " libvorbis");
            // ffmpeg's native decoder disagrees with libvorbis on ffmpeg's own encoder output, so it only checks libvorbis encodes.
            var b = fx.Padded ? Difference(d, native) : Compare(d, native, fx.Name + " native");
            lines.Add(fx.Name + " max " + a.Max.ToString("0.0E0", CultureInfo.InvariantCulture) + "/" + b.Max.ToString("0.0E0", CultureInfo.InvariantCulture) +
                " rms " + a.Rms.ToString("0.0E0", CultureInfo.InvariantCulture) + "/" + b.Rms.ToString("0.0E0", CultureInfo.InvariantCulture));
        }
        byte[] chained = File.ReadAllBytes(FixturePath(ChainedFixture));
        var cd = DecodeAll(chained);
        string firstLink = Path.Combine(scratchDir, "chained-first-link.ogg");
        File.WriteAllBytes(firstLink, Slice(chained, 0, (int)cd.LinkEnd));
        Compare(cd, Reference(firstLink, true, 1), "chained first link libvorbis");
        var md = DecodeAll(File.ReadAllBytes(FixturePath(MuxedFixture)));
        Compare(md, Reference(FixturePath(MuxedFixture), true, 1), "Theora multiplexed libvorbis");
        foreach (var syn in SyntheticStreams())
        {
            string path = Path.Combine(scratchDir, syn.Name + ".ogg");
            File.WriteAllBytes(path, syn.Data);
            var d = DecodeAll(syn.Data);
            float[] lib = Reference(path, true, d.Src), native = null;
            string nativeResult;
            try { native = Reference(path, false, d.Src); nativeResult = null; }
            catch (Exception ex) { nativeResult = ex.Message.Contains("lookup type") ? "cannot decode codebook lookup type 2" : "fails: " + ex.Message.Split('\n')[0].Trim(); }
            Check(d.Frames == lib.Length / d.Out, "Synthetic frame count equals libvorbis " + syn.Name);
            var a = Compare(d, lib, syn.Name + " libvorbis");
            if (syn.NativeOracle)
            {
                Check(native != null && d.Frames == native.Length / d.Out, "Synthetic frame count equals ffmpeg native " + syn.Name);
                nativeResult = Compare(d, native, syn.Name + " native").Max.ToString("0.0E0", CultureInfo.InvariantCulture);
            }
            else if (native != null)
            {
                // ffmpeg's native decoder diverges on multi-submap and coupled synthetic streams. libvorbis is the reference.
                double diff = 0;
                for (long i = 0; i < Math.Min(native.Length, d.Samples.Length); i++) diff = Math.Max(diff, Math.Abs(native[i] - d.Samples[i]));
                nativeResult = "diverges by up to " + F(diff, "0.0000");
            }
            lines.Add(syn.Name + " libvorbis max " + a.Max.ToString("0.0E0", CultureInfo.InvariantCulture) + ", native " + nativeResult);
        }
        report.Add("error vs ffmpeg libvorbis/native decoders per committed fixture:");
        foreach (string l in lines) report.Add("  " + l);
        Console.WriteLine("committed fixtures match ffmpeg at full length");
    }

    // ---- ffmpeg matrix (scratch) ----

    static void MatrixChecks()
    {
        string dir = Path.Combine(scratchDir, ScratchVersion + "-matrix");
        Directory.CreateDirectory(dir);
        var music = new Signal("music", 51);
        var mix = new Signal("mix", 52);
        var cases = new List<Fixture>();
        for (int q = -1; q <= 10; q++) cases.Add(new Fixture("q" + q, mix, 2, 44100, 44100 * 4, "-c:a libvorbis -q:a " + q));
        foreach (int rate in new[] { 8000, 11025, 16000, 22050, 24000, 32000, 44100, 48000, 88200, 96000, 176400, 192000 })
            cases.Add(new Fixture("rate" + rate, music, 2, rate, rate * 3, "-c:a libvorbis -q:a 3"));
        for (int channels = 1; channels <= 8; channels++) cases.Add(new Fixture("ch" + channels, music, channels, 44100, 44100 * 3, "-c:a libvorbis -q:a 3"));
        cases.Add(new Fixture("bitrate-managed", mix, 2, 44100, 44100 * 4, "-c:a libvorbis -b:a 96k -minrate 96k -maxrate 96k"));
        cases.Add(new Fixture("transients-q8", new Signal("transients", 53), 2, 48000, 48000 * 3, "-c:a libvorbis -q:a 8"));
        cases.Add(new Fixture("native-stereo48", mix, 2, 48000, 48000 * 3, "-c:a vorbis -strict experimental") { Padded = true });
        cases.Add(new Fixture("native-stereo8", music, 2, 8000, 8000 * 5, "-c:a vorbis -strict experimental") { Padded = true });
        cases.Add(new Fixture("native-q10", mix, 2, 44100, 44100 * 3, "-c:a vorbis -strict experimental -q:a 10") { Padded = true });
        var worst = new Dictionary<string, double>();
        var worstRms = new Dictionary<string, double>();
        foreach (var fx in cases)
        {
            string path = Path.Combine(dir, fx.Name + ".ogg");
            if (!File.Exists(path)) EncodeFromSignal(fx.Signal, fx.Channels, fx.Rate, fx.Frames, fx.Args, path);
            var d = DecodeAll(File.ReadAllBytes(path));
            Check(d.Src == fx.Channels && d.Rate == fx.Rate, "Matrix properties " + fx.Name);
            if (!fx.Padded) Check(d.Frames == fx.Frames, "Matrix exact source length " + fx.Name);
            float[] lib = Reference(path, true, d.Src), native = Reference(path, false, d.Src);
            Check(d.Frames == lib.Length / d.Out && d.Frames == native.Length / d.Out, "Matrix frame count equals ffmpeg " + fx.Name + " (" + d.Frames + " vs " + lib.Length / d.Out + ")");
            var a = Compare(d, lib, "matrix " + fx.Name + " libvorbis");
            var b = fx.Padded ? Difference(d, native) : Compare(d, native, "matrix " + fx.Name + " native");
            if (fx.Padded) nativeEncoderDivergence = Math.Max(nativeEncoderDivergence, b.Max);
            string cls = fx.Name.StartsWith("rate") ? "rates 8-192 kHz" : fx.Name.StartsWith("ch") ? "channels 1-8" : fx.Name.StartsWith("native") ? "native encoder" : "qualities and modes";
            double m = fx.Padded ? a.Max : Math.Max(a.Max, b.Max), r = fx.Padded ? a.Rms : Math.Max(a.Rms, b.Rms), prev;
            if (!worst.TryGetValue(cls, out prev) || m > prev) worst[cls] = m;
            if (!worstRms.TryGetValue(cls, out prev) || r > prev) worstRms[cls] = r;
            if (fx.Name == "transients-q8") Check(d.Stats.ShortBlocks > 0, "Transient matrix case uses short blocks");
        }
        report.Add("ffmpeg matrix worst error per class (max abs, rms), over both ffmpeg decoders, libvorbis only for native encodes:");
        foreach (var kv in worst) report.Add("  " + kv.Key + ": " + kv.Value.ToString("0.0E0", CultureInfo.InvariantCulture) + ", " + worstRms[kv.Key].ToString("0.0E0", CultureInfo.InvariantCulture));
        report.Add("  ffmpeg's native decoder differs from libvorbis and this decoder by up to " + F(nativeEncoderDivergence, "0.000") + " on ffmpeg native encodes");
        Console.WriteLine("ffmpeg matrix verified (" + cases.Count + " encodes)");
    }

    // ---- 5-minute file (scratch) ----

    static void LongFileChecks()
    {
        string dir = Path.Combine(scratchDir, ScratchVersion + "-long");
        Directory.CreateDirectory(dir);
        var music = new Signal("mix", 61);
        long frames = 44100L * 300;
        string path = Path.Combine(dir, "stereo-5min-q5.ogg");
        if (!File.Exists(path)) EncodeFromSignal(music, 2, 44100, frames, "-c:a libvorbis -q:a 5", path);
        byte[] data = File.ReadAllBytes(path);

        double best = double.MaxValue;
        for (int pass = 0; pass < 2; pass++)
        {
            var sw = Stopwatch.StartNew();
            using (var d = new VorbisDecoder(new MemoryStream(data), CancellationToken.None))
            {
                var buffer = new float[8192];
                while (d.Read(buffer, 0, buffer.Length) > 0) { }
            }
            best = Math.Min(best, sw.Elapsed.TotalSeconds);
        }
        double speed = 300.0 / best;
        report.Add("decode speed " + F(speed, "0") + "x real time on " + RuntimeName() + " (5 min 44.1 kHz stereo q5, " + (data.Length / 1024) + " KB, " + F(best, "0.00") + " s)");
        Check(speed > 20, "Decode faster than 20x real time");

        // Full comparison with the reference decoder, streamed from its raw output.
        string raw = ReferenceFile(path, true);
        using (var d = new VorbisDecoder(File.OpenRead(path), CancellationToken.None))
        using (var r = new BinaryReader(File.OpenRead(raw)))
        {
            Check(d.Frames == frames && r.BaseStream.Length == frames * 8, "5 min length equals source and ffmpeg");
            var buffer = new float[8192];
            double max = 0;
            int got;
            while ((got = d.Read(buffer, 0, buffer.Length)) > 0)
                for (int i = 0; i < got; i++) max = Math.Max(max, Math.Abs(buffer[i] - r.ReadSingle()));
            Check(max <= Tolerance, "5 min full decode within tolerance of libvorbis (max " + max + ")");
            report.Add("5 min full decode max error vs libvorbis " + max.ToString("0.0E0", CultureInfo.InvariantCulture));
        }
        LongSeeks("5 min", path, raw, 2, frames, 60);
    }

    // Seeks checked against the reference decoder's raw output and against this decoder's own linear decode.
    static void LongSeeks(string name, string path, string raw, int ch, long frames, int count)
    {
        var rng = new Rng(2024);
        var targets = new List<long> { frames - 1, 0, frames - 3000, 1 };
        while (targets.Count < count) targets.Add((long)(rng.NextDouble() * frames));
        const int span = 3000;
        var slices = new Dictionary<long, float[]>();
        using (var d = new VorbisDecoder(File.OpenRead(path), CancellationToken.None))
        using (var r = raw == null ? null : new BinaryReader(File.OpenRead(raw)))
        {
            var buffer = new float[span * ch];
            long maxPackets = 0;
            double maxMs = 0, totalMs = 0, maxErr = 0;
            foreach (long target in targets)
            {
                long before = d.Statistics.Packets;
                var sw = Stopwatch.StartNew();
                d.Seek(target);
                // Seek cost is what it takes to produce the first frame at the target.
                int got = d.Read(buffer, 0, ch);
                double ms = sw.Elapsed.TotalMilliseconds;
                long cost = d.Statistics.Packets - before;
                got += d.Read(buffer, ch, buffer.Length - ch);
                long n = Math.Min(span, frames - target);
                Check(got == n * ch, "Long seek read length " + name);
                maxPackets = Math.Max(maxPackets, cost);
                maxMs = Math.Max(maxMs, ms);
                totalMs += ms;
                var copy = new float[got];
                Array.Copy(buffer, copy, got);
                slices[target] = copy;
                if (r != null)
                {
                    r.BaseStream.Position = target * ch * 4;
                    for (int i = 0; i < got; i++) maxErr = Math.Max(maxErr, Math.Abs(buffer[i] - r.ReadSingle()));
                }
                Check(cost <= 3, "Seek synthesises only the priming packet and the target packet " + name + " (" + cost + ")");
            }
            if (r != null) Check(maxErr <= Tolerance, "Long seeks within tolerance of libvorbis " + name + " (max " + maxErr + ")");
            report.Add("seek " + name + ": " + F(totalMs / targets.Count, "0.0") + " ms average, " + F(maxMs, "0.0") + " ms worst, at most " + maxPackets +
                " packets synthesised to reach the target frame" + (r != null ? ", max error vs libvorbis " + maxErr.ToString("0.0E0", CultureInfo.InvariantCulture) : ""));
        }
        // Exactness: each slice equals a decode that reaches it linearly from 20000 frames earlier.
        using (var d = new VorbisDecoder(File.OpenRead(path), CancellationToken.None))
        {
            var buffer = new float[span * ch];
            foreach (var kv in slices)
            {
                long start = Math.Max(0, kv.Key - 20000);
                d.Seek(start);
                long at = start;
                var window = new float[(kv.Key - start) * ch + kv.Value.Length];
                int filled = 0;
                while (filled < window.Length)
                {
                    int got = d.Read(window, filled, Math.Min(window.Length - filled, buffer.Length));
                    if (got == 0) break;
                    filled += got;
                    at += got / ch;
                }
                int offset = (int)((kv.Key - start) * ch);
                for (int i = 0; i < kv.Value.Length; i++) if (window[offset + i] != kv.Value[i]) Check(false, "Seek " + name + " to " + kv.Key + " differs from a linear decode");
            }
            checks++;
        }
    }

    // ---- 60-minute file (scratch) ----

    static void HourFileChecks()
    {
        string dir = Path.Combine(scratchDir, ScratchVersion + "-long");
        Directory.CreateDirectory(dir);
        long frames = 44100L * 3600;
        string path = Path.Combine(dir, "stereo-60min-q0.ogg");
        if (!File.Exists(path))
        {
            var sw = Stopwatch.StartNew();
            EncodeFromSignal(new Signal("mix", 62), 2, 44100, frames, "-c:a libvorbis -q:a 0", path);
            Console.WriteLine("encoded 60 min scratch file in " + F(sw.Elapsed.TotalSeconds, "0") + " s");
        }
        var open = Stopwatch.StartNew();
        using (var d = new VorbisDecoder(File.OpenRead(path), CancellationToken.None))
        {
            Check(d.Frames == frames, "60 min length equals the source");
            report.Add("60 min open " + F(open.Elapsed.TotalMilliseconds, "0") + " ms (" + (new FileInfo(path).Length >> 20) + " MB)");
        }
        LongSeeks("60 min", path, null, 2, frames, 40);
        // Spot checks against the reference decoder, which decodes from the start for each.
        foreach (long target in new[] { frames / 2 + 12345, frames - 4000 })
        {
            float[] reference = ReferenceSlice(path, target, 2000, 2);
            using (var d = new VorbisDecoder(File.OpenRead(path), CancellationToken.None))
            {
                var buffer = new float[4000];
                d.Seek(target);
                int got = d.Read(buffer, 0, buffer.Length);
                Check(got == reference.Length, "60 min spot check length at " + target);
                double max = 0;
                for (int i = 0; i < got; i++) max = Math.Max(max, Math.Abs(buffer[i] - reference[i]));
                Check(max <= Tolerance, "60 min seek to " + target + " matches libvorbis (max " + max + ")");
            }
        }
    }

    // ---- Decoding helpers ----

    sealed class Decoded
    {
        public long Frames, StartGranule, LinkEnd; public int Src, Out, Rate, BlockSize1;
        public float[] Samples; public VorbisStatistics Stats; public string[] Codecs;
    }

    static Decoded DecodeAll(byte[] data)
    {
        using (var d = new VorbisDecoder(new MemoryStream(data, false), CancellationToken.None))
        {
            var r = new Decoded { Frames = d.Frames, Src = d.SourceChannels, Out = d.Channels, Rate = d.SampleRate, Stats = d.Statistics, StartGranule = d.StartGranule,
                LinkEnd = d.LinkEnd, BlockSize1 = d.BlockSize1, Codecs = d.GroupCodecs };
            Check(r.Frames < 50000000, "Test decode size");
            r.Samples = new float[r.Frames * r.Out];
            // An odd buffer length checks that Read returns whole frames only.
            var buffer = new float[1531 * r.Out + 1];
            long at = 0;
            int got;
            while ((got = d.Read(buffer, 0, buffer.Length)) > 0)
            {
                if (got % r.Out != 0) Check(false, "Read returned a partial frame");
                Array.Copy(buffer, 0, r.Samples, at, got);
                at += got;
            }
            Check(at == r.Frames * r.Out && d.Position == r.Frames, "Decoded length matches Frames");
            return r;
        }
    }

    static byte[] Slice(byte[] data, int offset, int length) { var r = new byte[length]; Array.Copy(data, offset, r, 0, length); return r; }

    // ffmpeg's native Vorbis decoder reorders to its own layouts: output channel i is Vorbis channel
    // Gather[n - 1][i]. Its libvorbis wrapper keeps the Vorbis order, although it labels the layout.
    static readonly int[][] Gather =
    {
        new[] { 0 }, new[] { 0, 1 }, new[] { 0, 2, 1 }, new[] { 0, 1, 2, 3 }, new[] { 0, 2, 1, 3, 4 }, new[] { 0, 2, 1, 5, 3, 4 },
        new[] { 0, 2, 1, 6, 5, 3, 4 }, new[] { 0, 2, 1, 7, 5, 6, 3, 4 },
    };

    // Reference decode in this decoder's output layout: ffmpeg's multichannel output is put back in Vorbis
    // order and folded with the same coefficients.
    static int[] Identity(int n) { var r = new int[n]; for (int i = 0; i < n; i++) r[i] = i; return r; }

    static float[] Reference(string path, bool libvorbis, int sourceChannels)
    {
        byte[] bytes = File.ReadAllBytes(ReferenceFile(path, libvorbis));
        var raw = new float[bytes.Length / 4];
        Buffer.BlockCopy(bytes, 0, raw, 0, raw.Length * 4);
        float[] result;
        if (sourceChannels <= 2) result = raw;
        else
        {
            float[] l, r;
            ChannelDownmix.Build(ChannelDownmix.Vorbis(sourceChannels), out l, out r);
            int[] gather = libvorbis || sourceChannels > 8 ? Identity(sourceChannels) : Gather[sourceChannels - 1];
            long frames = raw.Length / sourceChannels;
            result = new float[frames * 2];
            var vorbis = new float[sourceChannels];
            for (long f = 0; f < frames; f++)
            {
                for (int i = 0; i < sourceChannels; i++) vorbis[gather[i]] = raw[f * sourceChannels + i];
                float sl = 0, sr = 0;
                for (int c = 0; c < sourceChannels; c++) { sl += l[c] * vorbis[c]; sr += r[c] * vorbis[c]; }
                result[f * 2] = sl;
                result[f * 2 + 1] = sr;
            }
        }
        return result;
    }

    static string ReferenceFile(string path, bool libvorbis)
    {
        string raw = path + (libvorbis ? ".libvorbis.f32" : ".native.f32");
        if (raw.StartsWith(fixtureDir, StringComparison.OrdinalIgnoreCase)) raw = Path.Combine(scratchDir, "reference", Path.GetFileName(raw));
        Directory.CreateDirectory(Path.GetDirectoryName(raw));
        if (File.Exists(raw) && File.GetLastWriteTimeUtc(raw) >= File.GetLastWriteTimeUtc(path)) return raw;
        RunFfmpeg((libvorbis ? "-c:a libvorbis " : "") + "-i \"" + path + "\" -map 0:a:0 -f f32le -acodec pcm_f32le \"" + raw + "\"");
        return raw;
    }

    static float[] ReferenceSlice(string path, long start, int count, int ch)
    {
        string raw = Path.Combine(scratchDir, "slice.f32");
        RunFfmpeg("-c:a libvorbis -i \"" + path + "\" -af atrim=start_sample=" + start + ":end_sample=" + (start + count) + " -f f32le -acodec pcm_f32le \"" + raw + "\"");
        byte[] bytes = File.ReadAllBytes(raw);
        var result = new float[bytes.Length / 4];
        Buffer.BlockCopy(bytes, 0, result, 0, result.Length * 4);
        return result;
    }

    // ---- WAV and ffmpeg ----

    static readonly int[] ChannelMasks = { 0, 0x4, 0x3, 0x7, 0x33, 0x37, 0x3F, 0x70F, 0x63F };

    static void WriteWav(string path, Signal s, int channels, int rate, long frames)
    {
        using (var stream = new BufferedStream(File.Create(path), 1 << 20)) WriteWav(stream, s, channels, rate, frames);
    }

    static void WriteWav(Stream stream, Signal s, int channels, int rate, long frames)
    {
        long dataBytes = frames * channels * 2;
        bool extensible = channels > 2;
        var w = new BinaryWriter(stream);
        w.Write(Encoding.ASCII.GetBytes("RIFF"));
        w.Write((uint)Math.Min(uint.MaxValue, 4 + 8 + (extensible ? 40 : 16) + 8 + dataBytes));
        w.Write(Encoding.ASCII.GetBytes("WAVEfmt "));
        w.Write(extensible ? 40 : 16);
        w.Write((ushort)(extensible ? 0xFFFE : 1));
        w.Write((ushort)channels);
        w.Write(rate);
        w.Write(rate * channels * 2);
        w.Write((ushort)(channels * 2));
        w.Write((ushort)16);
        if (extensible)
        {
            w.Write((ushort)22);
            w.Write((ushort)16);
            w.Write(ChannelMasks[channels]);
            w.Write(new byte[] { 1, 0, 0, 0, 0, 0, 0x10, 0, 0x80, 0, 0, 0xAA, 0, 0x38, 0x9B, 0x71 });
        }
        w.Write(Encoding.ASCII.GetBytes("data"));
        w.Write((uint)Math.Min(uint.MaxValue, dataBytes));
        var block = new byte[4096 * channels * 2];
        for (long i = 0; i < frames; i += 4096)
        {
            int n = (int)Math.Min(4096, frames - i), o = 0;
            for (int f = 0; f < n; f++)
                for (int c = 0; c < channels; c++)
                {
                    short v = s.Sample16(c, i + f, rate);
                    block[o++] = (byte)v;
                    block[o++] = (byte)(v >> 8);
                }
            w.Write(block, 0, o);
        }
        w.Flush();
    }

    // Streams the source WAV to ffmpeg's standard input, so long sources never touch the disk.
    static void EncodeFromSignal(Signal s, int channels, int rate, long frames, string args, string output)
    {
        string temp = output + ".part.ogg";
        var info = new ProcessStartInfo(ffmpeg, "-hide_banner -loglevel error -y -f wav -i - " + args + " \"" + temp + "\"")
        {
            UseShellExecute = false,
            RedirectStandardInput = true,
            RedirectStandardError = true,
            RedirectStandardOutput = true,
            CreateNoWindow = true,
        };
        using (var process = Process.Start(info))
        {
            process.StandardOutput.ReadToEndAsync();
            var error = process.StandardError.ReadToEndAsync();
            using (var input = new BufferedStream(process.StandardInput.BaseStream, 1 << 20)) WriteWav(input, s, channels, rate, frames);
            process.WaitForExit();
            if (process.ExitCode != 0 || !File.Exists(temp)) throw new Exception("ffmpeg failed: " + error.Result);
        }
        File.Move(temp, output);
    }

    static void RunFfmpeg(string args)
    {
        var info = new ProcessStartInfo(ffmpeg, "-hide_banner -loglevel error -y " + args)
        {
            UseShellExecute = false,
            RedirectStandardError = true,
            RedirectStandardOutput = true,
            CreateNoWindow = true,
        };
        using (var process = Process.Start(info))
        {
            process.StandardOutput.ReadToEndAsync();
            string error = process.StandardError.ReadToEnd();
            process.WaitForExit();
            if (process.ExitCode != 0) throw new Exception("ffmpeg failed: " + error);
        }
    }
}

// Deterministic PRNG (splitmix64), identical on every runtime.
sealed class Rng
{
    ulong state;
    public Rng(ulong seed) { state = seed; }
    public ulong Next()
    {
        ulong z = state += 0x9E3779B97F4A7C15UL;
        z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
        z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
        return z ^ (z >> 31);
    }
    public double NextDouble() { return (Next() >> 11) * (1.0 / (1UL << 53)); }
    public int Below(int n) { return (int)(Next() % (ulong)n); }
    public void Fill(byte[] b) { for (int i = 0; i < b.Length; i++) b[i] = (byte)Next(); }
}

// Synthetic test signals, random access by frame so long files need no stored source.
sealed class Signal
{
    public readonly string Kind;
    public readonly uint Seed;
    public Signal(string kind, uint seed) { Kind = kind; Seed = seed; }

    public short Sample16(int ch, long i, int rate)
    {
        if (i < 0) return 0;
        double v = At(ch, i, rate) * 32767;
        return (short)Math.Max(-32768, Math.Min(32767, Math.Round(v)));
    }

    double At(int ch, long i, int rate)
    {
        switch (Kind)
        {
            case "silence": return 0;
            case "noise": return 0.4 * Noise(ch, i);
            case "transients": return Transients(ch, i, rate);
            case "mix":
                int segment = (int)((i * 4 / rate) % 6);
                if (segment == 1) return 0;
                if (segment == 3) return 0.3 * Noise(ch, i);
                if (segment == 4) return Transients(ch, i, rate);
                if (segment == 5) return 0.5 * Math.Sin(2 * Math.PI * 440 * (ch + 1) * i / rate);
                return Music(ch, i, rate);
            default: return Music(ch, i, rate);
        }
    }

    double Music(int ch, long i, int rate)
    {
        double t = (double)i / rate;
        double tc = t % 3.0;
        // Chirp from 200 Hz to 6 kHz over three seconds, plus a steady tone per channel and a little noise.
        double chirp = Math.Sin(2 * Math.PI * (200 * tc + 0.5 * (5800 / 3.0) * tc * tc) + ch * 0.7);
        double tone = Math.Sin(2 * Math.PI * (330 + 110 * ch) * t);
        return 0.35 * chirp + 0.25 * tone + 0.02 * Noise(ch, i);
    }

    double Transients(int ch, long i, int rate)
    {
        long period = rate / 9;
        long k = i % period;
        double env = Math.Exp(-(double)k / (rate * 0.003));
        return 0.7 * env * Noise(ch, i) + 0.05 * Math.Sin(2 * Math.PI * 220 * i / rate);
    }

    double Noise(int ch, long i)
    {
        ulong z = ((ulong)Seed << 40) ^ ((ulong)ch << 34) ^ (ulong)i;
        z += 0x9E3779B97F4A7C15UL;
        z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
        z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
        z ^= z >> 31;
        return (z >> 11) * (2.0 / (1UL << 53)) - 1;
    }
}

// Independent Ogg page writer and parser for building container variations.
static class TestOgg
{
    public sealed class PageRec { public long Offset; public int Size, Flags; public long Granule; public uint Serial, Seq; }
    public sealed class Parsed { public uint Serial; public List<byte[]> Packets = new List<byte[]>(); public List<long> Granules = new List<long>(); }

    public static uint Crc(byte[] data)
    {
        uint crc = 0;
        foreach (byte b in data)
        {
            crc ^= (uint)b << 24;
            for (int i = 0; i < 8; i++) crc = (crc & 0x80000000u) != 0 ? (crc << 1) ^ 0x04C11DB7u : crc << 1;
        }
        return crc;
    }

    public static byte[] Join(List<byte[]> parts)
    {
        var ms = new MemoryStream();
        foreach (var p in parts) ms.Write(p, 0, p.Length);
        return ms.ToArray();
    }

    // Pages parsed sequentially. Stops at the first byte that is not a whole page.
    public static List<PageRec> ParsePages(byte[] f)
    {
        var list = new List<PageRec>();
        int p = 0;
        while (p + 27 <= f.Length && f[p] == 'O' && f[p + 1] == 'g' && f[p + 2] == 'g' && f[p + 3] == 'S')
        {
            int n = f[p + 26];
            if (p + 27 + n > f.Length) break;
            int body = 0;
            for (int i = 0; i < n; i++) body += f[p + 27 + i];
            int size = 27 + n + body;
            if (p + size > f.Length) break;
            list.Add(new PageRec { Offset = p, Size = size, Flags = f[p + 5], Granule = BitConverter.ToInt64(f, p + 6), Serial = BitConverter.ToUInt32(f, p + 14), Seq = BitConverter.ToUInt32(f, p + 18) });
            p += size;
        }
        return list;
    }

    // Packets of the first serial with the granule of the page each ends on, or -1 when not last on it.
    public static Parsed ParsePackets(byte[] f)
    {
        var result = new Parsed();
        var pages = ParsePages(f);
        result.Serial = pages[0].Serial;
        var current = new MemoryStream();
        foreach (var pg in pages)
        {
            if (pg.Serial != result.Serial) continue;
            int n = f[pg.Offset + 26];
            int at = (int)pg.Offset + 27 + n;
            int lastEnd = -1;
            for (int i = 0; i < n; i++) if (f[pg.Offset + 27 + i] < 255) lastEnd = i;
            for (int i = 0; i < n; i++)
            {
                int v = f[pg.Offset + 27 + i];
                current.Write(f, at, v);
                at += v;
                if (v < 255)
                {
                    result.Packets.Add(current.ToArray());
                    result.Granules.Add(i == lastEnd ? pg.Granule : -1);
                    current = new MemoryStream();
                }
            }
        }
        return result;
    }

    // Splits packets into pages of at most maxBody body bytes, flushing after the listed packets. Each page
    // carries the granule of the last packet completed on it, or -1.
    public static List<byte[]> BuildPages(uint serial, List<byte[]> packets, List<long> granules, int maxBody, bool eos, HashSet<int> flushAfter, uint seq0)
    {
        var pages = new List<byte[]>();
        var lacing = new List<int>();
        var body = new MemoryStream();
        bool continued = false;
        long granule = -1;
        uint seq = seq0;
        Action<bool> flush = next =>
        {
            if (lacing.Count == 0) return;
            pages.Add(Page(serial, seq++, (pages.Count == 0 ? 2 : 0) | (continued ? 1 : 0), granule, lacing, body.ToArray()));
            lacing.Clear();
            body.SetLength(0);
            continued = next;
            granule = -1;
        };
        for (int k = 0; k < packets.Count; k++)
        {
            byte[] p = packets[k];
            int offset = 0;
            int segments = p.Length / 255 + 1;
            for (int s = 0; s < segments; s++)
            {
                int v = s < segments - 1 ? 255 : p.Length % 255;
                if (lacing.Count == 255 || (lacing.Count > 0 && body.Length + v > maxBody)) flush(s > 0);
                lacing.Add(v);
                body.Write(p, offset, v);
                offset += v;
            }
            granule = granules[k];
            if (flushAfter != null && flushAfter.Contains(k)) flush(false);
        }
        flush(false);
        if (eos)
        {
            byte[] last = pages[pages.Count - 1];
            last[5] |= 4;
            SetCrc(last, 0);
        }
        return pages;
    }

    public static byte[] Page(uint serial, uint seq, int flags, long granule, List<int> lacing, byte[] body)
    {
        var page = new byte[27 + lacing.Count + body.Length];
        Encoding.ASCII.GetBytes("OggS").CopyTo(page, 0);
        page[5] = (byte)flags;
        BitConverter.GetBytes(granule).CopyTo(page, 6);
        BitConverter.GetBytes(serial).CopyTo(page, 14);
        BitConverter.GetBytes(seq).CopyTo(page, 18);
        page[26] = (byte)lacing.Count;
        for (int i = 0; i < lacing.Count; i++) page[27 + i] = (byte)lacing[i];
        body.CopyTo(page, 27 + lacing.Count);
        SetCrc(page, 0);
        return page;
    }

    static void SetCrc(byte[] f, int offset)
    {
        int n = f[offset + 26], size = 27 + n;
        for (int i = 0; i < n; i++) size += f[offset + 27 + i];
        var copy = new byte[size];
        Array.Copy(f, offset, copy, 0, size);
        copy[22] = copy[23] = copy[24] = copy[25] = 0;
        BitConverter.GetBytes(Crc(copy)).CopyTo(f, offset + 22);
    }

    // Recomputes the CRC of every page found by its capture pattern.
    public static void FixCrcs(byte[] f)
    {
        for (int p = 0; p + 27 <= f.Length; p++)
        {
            if (f[p] != 'O' || f[p + 1] != 'g' || f[p + 2] != 'g' || f[p + 3] != 'S') continue;
            int n = f[p + 26], size = 27 + n;
            if (p + 27 + n > f.Length) break;
            for (int i = 0; i < n; i++) size += f[p + 27 + i];
            if (p + size > f.Length) break;
            SetCrc(f, p);
            p += size - 1;
        }
    }

    // Beginning-of-stream pages of both first, then each stream's other header pages, then the rest alternately.
    public static byte[] Interleave(List<byte[]> a, List<byte[]> b, int aHeaders, int bHeaders)
    {
        var parts = new List<byte[]> { a[0], b[0] };
        int ia = 1, ib = 1;
        while (ia < aHeaders && ia < a.Count) parts.Add(a[ia++]);
        while (ib < bHeaders && ib < b.Count) parts.Add(b[ib++]);
        while (ia < a.Count || ib < b.Count)
        {
            if (ia < a.Count) parts.Add(a[ia++]);
            if (ib < b.Count) parts.Add(b[ib++]);
        }
        return Join(parts);
    }
}

// LSB-first bit writer for hand-built Vorbis packets.
sealed class BitPacker
{
    readonly MemoryStream ms = new MemoryStream();
    ulong acc;
    int bits;
    public long BitCount;

    public void Put(ulong value, int n)
    {
        if (n > 32) { Put(value & 0xFFFFFFFFUL, 32); Put(value >> 32, n - 32); return; }
        acc |= (value & ((1UL << n) - 1)) << bits;
        bits += n;
        BitCount += n;
        while (bits >= 8)
        {
            ms.WriteByte((byte)acc);
            acc >>= 8;
            bits -= 8;
        }
    }

    public byte[] ToArray()
    {
        var copy = new MemoryStream();
        byte[] done = ms.ToArray();
        copy.Write(done, 0, done.Length);
        if (bits > 0) copy.WriteByte((byte)acc);
        return copy.ToArray();
    }
}

// Hand-built Vorbis streams whose setup exercises what libvorbis never emits: residue type 0, lookup type 2
// with sequence_p, sparse and ordered codebooks, codewords longer than the fast table, a single-entry
// codebook, two submaps, chained coupling, floor classes with subclasses and a floor wider than the block.
// Audio packets are random but valid bitstreams, decoded as the oracle by ffmpeg.
static class TestVorbis
{
    const int Bs0 = 256, Bs1 = 2048;

    sealed class Book
    {
        public int Dims, Entries, Lookup, ValueBits;
        public byte[] Lengths;
        public uint[] Codes;
        public bool Ordered, Sparse, Sequence;
        public double Min, Delta;
        public int[] Mult;
        public List<int> Used = new List<int>();
    }

    sealed class Floor { public int[] PartClass; public int[] ClassDims, ClassSub, ClassMaster; public int[][] SubBooks; public int Mult, RangeBits; public int[] X; }
    sealed class Residue { public int Type, Begin, End, PSize, Classes, ClassBook; public int[][] Books; }
    sealed class Mapping { public int Submaps; public int[] Mag, Ang, Mux, Floor, Res; }

    public static uint Pack(double v)
    {
        if (v == 0) return 0;
        uint sign = v < 0 ? 0x80000000u : 0;
        double m = Math.Abs(v);
        int e = 788;
        while (m < (1 << 20)) { m *= 2; e--; }
        while (m >= (1 << 21)) { m /= 2; e++; }
        if (m != Math.Floor(m)) throw new Exception("value not exactly packable");
        return sign | ((uint)e << 21) | (uint)m;
    }

    static byte[] Balanced(int n)
    {
        int l = VorbisCodec.ILog(n - 1);
        int shorter = (1 << l) - n;
        var lengths = new byte[n];
        for (int i = 0; i < n; i++) lengths[i] = (byte)(i < shorter ? l - 1 : l);
        if (n == 1) lengths[0] = 1;
        return lengths;
    }

    static Book MakeBook(int dims, byte[] lengths, int lookup, bool ordered, bool sparse)
    {
        var b = new Book { Dims = dims, Entries = lengths.Length, Lengths = lengths, Lookup = lookup, Ordered = ordered, Sparse = sparse };
        b.Codes = new uint[lengths.Length];
        int used = 0;
        for (int i = 0; i < lengths.Length; i++) if (lengths[i] > 0) { used++; b.Used.Add(i); }
        if (used > 1 && !VorbisCodebook.AssignCodewords(lengths, b.Codes)) throw new Exception("test codebook overspecified");
        return b;
    }

    static void WriteBook(BitPacker w, Book b, string fault)
    {
        w.Put(fault == "codebooksync" ? 0x564343u : 0x564342u, 24);
        w.Put((uint)b.Dims, 16);
        w.Put(fault == "hugebook" ? 0xFFFFFFu : (uint)b.Entries, 24);
        w.Put(b.Ordered ? 1u : 0u, 1);
        if (b.Ordered)
        {
            int current = 0, len = b.Lengths[0];
            w.Put((uint)(len - 1), 5);
            while (current < b.Entries)
            {
                int number = 0;
                while (current + number < b.Entries && b.Lengths[current + number] == len) number++;
                w.Put((uint)number, VorbisCodec.ILog(b.Entries - current));
                current += number;
                len++;
            }
        }
        else
        {
            w.Put(b.Sparse ? 1u : 0u, 1);
            foreach (byte len in b.Lengths)
            {
                if (b.Sparse) w.Put(len > 0 ? 1u : 0u, 1);
                if (len > 0 || !b.Sparse) w.Put((uint)(len - 1), 5);
            }
        }
        w.Put(fault == "lookuptype" ? 3u : (uint)b.Lookup, 4);
        if (b.Lookup != 0)
        {
            w.Put(Pack(b.Min), 32);
            w.Put(Pack(b.Delta), 32);
            w.Put((uint)(b.ValueBits - 1), 4);
            w.Put(b.Sequence ? 1u : 0u, 1);
            foreach (int m in b.Mult) w.Put((uint)m, b.ValueBits);
        }
    }

    static void Code(BitPacker w, Book b, int entry)
    {
        if (b.Used.Count == 1) { w.Put(0, b.Lengths[entry]); return; }
        uint code = b.Codes[entry];
        for (int i = 0; i < b.Lengths[entry]; i++) w.Put((code >> (31 - i)) & 1, 1);
    }

    // Builds a stream of the given channel count. Truncated packets end mid-residue to exercise the
    // end-of-packet rules. endTrim shortens the final granule. A fault name corrupts the setup header.
    // nativeCompatible avoids lookup type 2 and keeps residue 0 and 1 ends within a short block, which ffmpeg's
    // native decoder needs although the specification clamps them. Residue 2 partitions stay multiples of the
    // channel count: libvorbis deinterleaves a partition that starts mid-frame from channel 0, against the
    // specification, so no reference decoder can check that case.
    public static byte[] Build(int channels, int packetCount, ulong seed, bool truncate, int endTrim, out long frames, string fault = null, bool nativeCompatible = false)
    {
        var rng = new Rng(seed);
        var books = new List<Book>();
        books.Add(MakeBook(1, new byte[] { 2, 2, 2, 2 }, 0, false, false));                          // 0 floor masterbook
        books.Add(MakeBook(1, Balanced(32), 0, true, false));                                         // 1 floor values, ordered
        books.Add(MakeBook(2, Balanced(9), 0, true, false));                                          // 2 residue classbook, 3 classes squared
        var b3 = MakeBook(4, Balanced(81), 1, false, false);                                          // 3 lookup 1, {-1, 0, 1} to the fourth
        b3.Min = -1; b3.Delta = 1; b3.ValueBits = 2; b3.Mult = new[] { 0, 1, 2 };
        books.Add(b3);
        var l4 = new byte[16];
        byte[] bal13 = Balanced(13);
        for (int i = 0, k = 0; i < 16; i++) l4[i] = (i == 3 || i == 7 || i == 11) ? (byte)0 : bal13[k++];
        var b4 = MakeBook(2, l4, nativeCompatible ? 1 : 2, false, true);                                    // 4 lookup 2, sparse, sequence_p
        b4.Min = -0.5; b4.Delta = 0.125; b4.ValueBits = 3; b4.Sequence = true; b4.Mult = new int[nativeCompatible ? 4 : 32];
        for (int i = 0; i < b4.Mult.Length; i++) b4.Mult[i] = rng.Below(8);
        books.Add(b4);
        var l5 = new byte[40];
        for (int i = 0; i < 16; i++) l5[i * 2 + 5] = (byte)Math.Min(i + 1, 15);                        // lengths 1..15, 15: complete
        var b5 = MakeBook(1, l5, 1, false, true);                                                     // 5 long codewords, sparse, lookup 1 of dimension 1
        b5.Min = -2.5; b5.Delta = 0.125; b5.ValueBits = 6; b5.Mult = new int[40];
        for (int i = 0; i < 40; i++) b5.Mult[i] = i;
        books.Add(b5);
        var b6 = MakeBook(2, new byte[] { 1 }, 1, false, false);                                      // 6 single entry
        b6.Min = 0; b6.Delta = 0.25; b6.ValueBits = 1; b6.Mult = new[] { 1 };
        books.Add(b6);

        if (fault == "residuebook") { books[3].Lookup = 0; }

        var floors = new List<Floor>
        {
            new Floor { PartClass = new[] { 0, 1, 1 }, ClassDims = new[] { 2, 3 }, ClassSub = new[] { 0, 2 }, ClassMaster = new[] { 0, 0 },
                SubBooks = new[] { new[] { 1 }, new[] { -1, 1, 1, 1 } }, Mult = 2, RangeBits = 7, X = new[] { 0, 128, 32, 64, 8, 16, 24, 96, 80, 112 } },
            new Floor { PartClass = new[] { 0, 1, 1, 2 }, ClassDims = new[] { 2, 3, 1 }, ClassSub = new[] { 0, 2, 1 }, ClassMaster = new[] { 0, 0, 0 },
                SubBooks = new[] { new[] { 1 }, new[] { -1, 1, 1, 1 }, new[] { 1, -1 } }, Mult = 2, RangeBits = 10, X = new[] { 0, 1024, 256, 512, 64, 128, 192, 768, 640, 896, 960 } },
        };
        if (fault == "duplicatex") floors[0].X[5] = 8;
        var residues = new List<Residue>
        {
            new Residue { Type = 0, Begin = 0, End = nativeCompatible ? 128 : 1024, PSize = 16, Classes = 3, ClassBook = 2, Books = new[] { new int[0], new[] { 3 }, new[] { 3, 4 } } },
            new Residue { Type = 1, Begin = 32, End = nativeCompatible ? 128 : 896, PSize = 32, Classes = 3, ClassBook = 2, Books = new[] { new int[0], new[] { 5 }, new[] { 6, -1, 4 } } },
            new Residue { Type = 2, Begin = 0, End = 1500 * Math.Max(1, channels) / 2, PSize = 24, Classes = 3, ClassBook = 2, Books = new[] { new int[0], new[] { 3 }, new[] { 4, 3, -1, -1, -1, -1, -1, 6 } } },
        };
        var mappings = new List<Mapping>();
        var m0 = new Mapping { Submaps = channels > 1 ? 2 : 1, Mux = new int[channels], Floor = new[] { 0, 0 }, Res = new[] { 0, 1 } };
        for (int c = 0; c < channels; c++) m0.Mux[c] = channels > 1 ? c % 2 : 0;
        if (channels >= 3) { m0.Mag = new[] { 0, 1 }; m0.Ang = new[] { 1, 2 }; }
        else if (channels == 2) { m0.Mag = new[] { 0 }; m0.Ang = new[] { 1 }; }
        else { m0.Mag = new int[0]; m0.Ang = new int[0]; }
        if (fault == "coupling") { m0.Ang[0] = m0.Mag[0]; }
        mappings.Add(m0);
        var m1 = new Mapping { Submaps = 1, Mux = new int[channels], Floor = new[] { 1 }, Res = new[] { 2 }, Mag = channels >= 2 ? new[] { 0 } : new int[0], Ang = channels >= 2 ? new[] { channels - 1 } : new int[0] };
        mappings.Add(m1);
        mappings.Add(new Mapping { Submaps = 1, Mux = new int[channels], Floor = new[] { 1 }, Res = new[] { 1 }, Mag = new int[0], Ang = new int[0] });
        int[] modeFlag = { 0, 1, 0, 1 }, modeMap = { 0, 1, 2, 0 }, setupMap = { 0, 1, 2, 0 };
        if (fault == "modemapping") setupMap[3] = 5;

        // Identification and comment headers.
        var ident = new byte[30];
        ident[0] = 1; Encoding.ASCII.GetBytes("vorbis").CopyTo(ident, 1);
        ident[11] = (byte)channels;
        BitConverter.GetBytes(44100).CopyTo(ident, 12);
        ident[28] = (byte)((VorbisCodec.ILog(Bs1 - 1) << 4) | VorbisCodec.ILog(Bs0 - 1));
        ident[29] = 1;
        var comment = new MemoryStream();
        comment.WriteByte(3); comment.Write(Encoding.ASCII.GetBytes("vorbis"), 0, 6);
        byte[] vendor = Encoding.ASCII.GetBytes("Radio synthetic test stream");
        comment.Write(BitConverter.GetBytes(vendor.Length), 0, 4); comment.Write(vendor, 0, vendor.Length);
        comment.Write(BitConverter.GetBytes(0), 0, 4); comment.WriteByte(1);

        // Setup header.
        var w = new BitPacker();
        w.Put(5, 8);
        foreach (char ch in "vorbis") w.Put(ch, 8);
        w.Put((uint)(books.Count - 1), 8);
        foreach (var b in books) WriteBook(w, fault == "overspecified" && b == books[0] ? MakeBookUnchecked(1, new byte[] { 1, 1, 1 }) : b, fault);
        w.Put(0, 6);
        w.Put(fault == "timedomain" ? 1u : 0u, 16);
        w.Put((uint)(floors.Count - 1), 6);
        foreach (var f in floors)
        {
            w.Put(fault == "floor0" ? 0u : fault == "floortype" ? 2u : 1u, 16);
            w.Put((uint)f.PartClass.Length, 5);
            foreach (int c in f.PartClass) w.Put((uint)c, 4);
            for (int c = 0; c < f.ClassDims.Length; c++)
            {
                w.Put((uint)(f.ClassDims[c] - 1), 3);
                w.Put((uint)f.ClassSub[c], 2);
                if (f.ClassSub[c] > 0) w.Put((uint)f.ClassMaster[c], 8);
                foreach (int b in f.SubBooks[c]) w.Put((uint)(b + 1), 8);
            }
            w.Put((uint)(f.Mult - 1), 2);
            w.Put((uint)f.RangeBits, 4);
            for (int i = 2; i < f.X.Length; i++) w.Put((uint)f.X[i], f.RangeBits);
        }
        w.Put((uint)(residues.Count - 1), 6);
        foreach (var r in residues)
        {
            w.Put(fault == "residuetype" ? 3u : (uint)r.Type, 16);
            w.Put((uint)r.Begin, 24);
            w.Put((uint)r.End, 24);
            w.Put((uint)(r.PSize - 1), 24);
            w.Put((uint)(r.Classes - 1), 6);
            w.Put((uint)r.ClassBook, 8);
            foreach (int[] cb in r.Books)
            {
                int cascade = 0;
                for (int j = 0; j < cb.Length; j++) if (cb[j] >= 0) cascade |= 1 << j;
                w.Put((uint)(cascade & 7), 3);
                w.Put(cascade > 7 ? 1u : 0u, 1);
                if (cascade > 7) w.Put((uint)(cascade >> 3), 5);
            }
            foreach (int[] cb in r.Books) foreach (int b in cb) if (b >= 0) w.Put((uint)b, 8);
        }
        w.Put((uint)(mappings.Count - 1), 6);
        int chBits = VorbisCodec.ILog(channels - 1);
        foreach (var m in mappings)
        {
            w.Put(fault == "mappingtype" ? 1u : 0u, 16);
            w.Put(m.Submaps > 1 ? 1u : 0u, 1);
            if (m.Submaps > 1) w.Put((uint)(m.Submaps - 1), 4);
            w.Put(m.Mag.Length > 0 ? 1u : 0u, 1);
            if (m.Mag.Length > 0)
            {
                w.Put((uint)(m.Mag.Length - 1), 8);
                for (int i = 0; i < m.Mag.Length; i++) { w.Put((uint)m.Mag[i], chBits); w.Put((uint)m.Ang[i], chBits); }
            }
            w.Put(0, 2);
            if (m.Submaps > 1) foreach (int x in m.Mux) w.Put((uint)x, 4);
            for (int s = 0; s < m.Submaps; s++) { w.Put(0, 8); w.Put((uint)m.Floor[s], 8); w.Put((uint)m.Res[s], 8); }
        }
        w.Put(3, 6);
        for (int i = 0; i < 4; i++) { w.Put((uint)modeFlag[i], 1); w.Put(0, 16); w.Put(0, 16); w.Put((uint)setupMap[i], 8); }
        w.Put(fault == "framing" ? 0u : 1u, 1);

        var packets = new List<byte[]> { ident, comment.ToArray(), w.ToArray() };
        var granules = new List<long> { 0, 0, 0 };

        // Audio packets. Window flags follow the actual neighbours.
        var modes = new int[packetCount];
        for (int k = 0; k < packetCount; k++) modes[k] = (k / 5) % 3 == 1 ? (rng.Below(2) == 0 ? 0 : 2) : (rng.Below(4) == 0 ? 3 : 1);
        long end = 0;
        int previous = -1;
        for (int k = 0; k < packetCount; k++)
        {
            int mode = modes[k], flag = modeFlag[mode], n = flag == 1 ? Bs1 : Bs0;
            var p = new BitPacker();
            p.Put(0, 1);
            p.Put((uint)mode, 2);
            if (flag == 1)
            {
                p.Put(k > 0 && modeFlag[modes[k - 1]] == 1 ? 1u : 0u, 1);
                p.Put(k + 1 < packetCount && modeFlag[modes[k + 1]] == 1 ? 1u : 0u, 1);
            }
            var map = mappings[modeMap[mode]];
            var noResidue = new bool[channels];
            for (int c = 0; c < channels; c++)
            {
                var f = floors[map.Floor[map.Mux[c]]];
                bool nonzero = rng.Below(10) != 0;
                noResidue[c] = !nonzero;
                p.Put(nonzero ? 1u : 0u, 1);
                if (!nonzero) continue;
                p.Put((uint)(45 + rng.Below(20)), 7);
                p.Put((uint)(45 + rng.Below(20)), 7);
                foreach (int cls in f.PartClass)
                {
                    int cbits = f.ClassSub[cls], cval = 0;
                    if (cbits > 0)
                    {
                        cval = rng.Below(4);
                        Code(p, books[f.ClassMaster[cls]], cval);
                    }
                    for (int j = 0; j < f.ClassDims[cls]; j++)
                    {
                        int book = f.SubBooks[cls][cval & ((1 << cbits) - 1)];
                        cval >>= cbits;
                        if (book >= 0) Code(p, books[book], rng.Below(3) == 0 ? rng.Below(4) : 0);
                    }
                }
            }
            for (int s = 0; s < map.Mag.Length; s++)
                if (!noResidue[map.Mag[s]] || !noResidue[map.Ang[s]]) noResidue[map.Mag[s]] = noResidue[map.Ang[s]] = false;
            for (int s = 0; s < map.Submaps; s++)
            {
                var dnd = new List<bool>();
                for (int c = 0; c < channels; c++) if (map.Mux[c] == s) dnd.Add(noResidue[c]);
                WriteResidue(p, residues[map.Res[s]], books, dnd, n / 2, rng);
            }
            byte[] bytes = p.ToArray();
            // A cut packet keeps its mode bits, so its length still counts toward the granule.
            if (truncate && k % 4 == 2 && bytes.Length > 3) bytes = Cut(bytes, bytes.Length * 2 / 3);
            packets.Add(bytes);
            if (previous >= 0) end += previous / 4 + n / 4;
            previous = n;
            granules.Add(end);
        }
        granules[granules.Count - 1] -= endTrim;
        frames = granules[granules.Count - 1];
        return TestOgg.Join(TestOgg.BuildPages(0x5EED0000u + (uint)seed, packets, granules, 4000, true, new HashSet<int> { 0, 2 }, 0));
    }

    static Book MakeBookUnchecked(int dims, byte[] lengths)
    {
        var b = new Book { Dims = dims, Entries = lengths.Length, Lengths = lengths, Codes = new uint[lengths.Length] };
        for (int i = 0; i < lengths.Length; i++) b.Used.Add(i);
        return b;
    }

    static byte[] Cut(byte[] b, int n) { var r = new byte[n]; Array.Copy(b, r, n); return r; }

    static void WriteResidue(BitPacker p, Residue r, List<Book> books, List<bool> dnd, int n2, Rng rng)
    {
        int count = dnd.Count;
        bool any = false;
        foreach (bool x in dnd) if (!x) any = true;
        int vectors = count, size = n2;
        var skip = new List<bool>(dnd);
        if (r.Type == 2)
        {
            if (!any || count == 0) return;
            vectors = 1;
            size = n2 * count;
            skip = new List<bool> { false };
        }
        int from = Math.Min(r.Begin, size), to = Math.Min(r.End, size);
        if (to - from <= 0) return;
        int partitions = (to - from) / r.PSize;
        var classBook = books[r.ClassBook];
        int perWord = classBook.Dims;
        var classes = new int[vectors][];
        for (int j = 0; j < vectors; j++) classes[j] = new int[partitions + perWord];
        for (int pass = 0; pass < 8; pass++)
        {
            int part = 0;
            while (part < partitions)
            {
                if (pass == 0)
                    for (int j = 0; j < vectors; j++)
                    {
                        if (skip[j]) continue;
                        int temp = 0;
                        for (int i = 0; i < perWord; i++)
                        {
                            int c = rng.Below(r.Classes);
                            classes[j][part + i] = c;
                            temp = temp * r.Classes + c;
                        }
                        Code(p, classBook, temp);
                    }
                for (int i = 0; i < perWord && part < partitions; i++, part++)
                    for (int j = 0; j < vectors; j++)
                    {
                        if (skip[j]) continue;
                        int[] cb = r.Books[classes[j][part]];
                        int book = pass < cb.Length ? cb[pass] : -1;
                        if (book < 0) continue;
                        var b = books[book];
                        int entries = r.Type == 0 ? r.PSize / b.Dims : (r.PSize + b.Dims - 1) / b.Dims;
                        for (int e = 0; e < entries; e++) Code(p, b, b.Used[rng.Below(b.Used.Count)]);
                    }
            }
        }
    }
}
